DO $op$
DECLARE src uuid := 'd73deb33-a0f9-41bb-ad4d-637cd5d159b6'; chi uuid := 'a9f08834-6fb2-4d4b-8bb1-730f59336da6'; n uuid; np uuid; before_blocks jsonb; chi_before jsonb; total_before numeric; total_after numeric; c jsonb; count_changed int:=0;
BEGIN
PERFORM 1 FROM public.fee_proposals WHERE id IN(src,chi) FOR UPDATE;
PERFORM 1 FROM public.psa_proposal_blocks WHERE proposal_id IN (SELECT main_proposal_id FROM public.fee_proposals WHERE id IN(src,chi)) FOR UPDATE;
IF (SELECT quote_status FROM public.fee_proposals WHERE id=src)<>'draft' THEN RAISE EXCEPTION 'Oleiro no longer Draft'; END IF;
SELECT jsonb_agg(to_jsonb(b) ORDER BY id) INTO before_blocks FROM public.psa_proposal_blocks b WHERE proposal_id=(SELECT main_proposal_id FROM public.fee_proposals WHERE id=src);
SELECT jsonb_build_object('quote',to_jsonb(q),'blocks',(SELECT jsonb_agg(to_jsonb(b) ORDER BY id) FROM public.psa_proposal_blocks b WHERE proposal_id=q.main_proposal_id)) INTO chi_before FROM public.fee_proposals q WHERE id=chi;
total_before:=public.fee_proposal_resolved_value(src);
FOR c IN SELECT value FROM jsonb_array_elements($changes$[{"id": "36752430-456a-4072-90d1-5721c6b37570", "title": "Carta", "sort_order": 20, "before": {"html": "<p>Agradecemos a oportunidade de apresentar a nossa proposta de serviços de arquitectura para {{project_name}}.</p><p>O âmbito proposto abrange o programa, o estudo prévio, o anteprojecto e a submissão do pedido de informação prévia, o licenciamento e o projecto de execução, bem como o apoio ao concurso de construção e o acompanhamento da fase de obra em regime de avença.</p><p>A proposta organiza-se em {{stage_count}} fases, com honorários totais de {{total_fee}} e uma duração estimada de {{estimated_duration}} a partir do início dos trabalhos, dependente da articulação entre os intervenientes e dos prazos de apreciação pelas entidades competentes.</p><p>Ficamos à disposição para esclarecer a proposta e ajustar a sua articulação às vossas necessidades. Será um gosto colaborar convosco.</p>", "aiFigures": {"total_fee": "203 300 €", "client_name": "GREATLUCK INVESTIMENTOS IMOBILIARIOS LDA", "stage_count": "1", "project_name": "Travessa do Oleiro", "proposal_date": "11/11/2026", "proposal_number": "26117", "contact_salutation": "—", "estimated_duration": "43 semanas"}, "letterSettings": {"templates": {}, "signatoryName": "Luis Pedra Silva", "signatureData": "/__l5e/assets-v1/21490fcf-fd50-4c3a-93bd-3ff340f43065/luis-pedra-silva-signature.jpg"}, "pageBreakAfter": true, "pageBreakBefore": true}, "after": {"html": "<p>Agradecemos a oportunidade de apresentar a nossa proposta de serviços de arquitectura para {{project_name}}.</p><p>A PSA será a autora do projeto de arquitetura, trabalhando em parceria com o designer de interiores indicado pelo Cliente e integrando as suas soluções nos projetos de licenciamento e de execução. O âmbito proposto abrange o programa, o estudo prévio, o anteprojecto e a submissão do pedido de informação prévia, o licenciamento e o projecto de execução, bem como o apoio ao concurso de construção e o acompanhamento da fase de obra em regime de avença.</p><p>A proposta organiza-se em {{stage_count}} fases, com honorários totais de {{total_fee}} e uma duração estimada de {{estimated_duration}} a partir do início dos trabalhos, dependente da articulação entre os intervenientes e dos prazos de apreciação pelas entidades competentes.</p><p>O desenvolvimento de cada fase depende da receção atempada dos elementos do Cliente e do designer de interiores. O projeto de design de interiores, incluindo mobiliário, equipamento e decoração (FF&amp;E), é da responsabilidade do designer de interiores indicado pelo Cliente e está excluído dos serviços da PSA. Ficamos à disposição para esclarecer a proposta e ajustar a sua articulação às vossas necessidades. Será um gosto colaborar convosco.</p>", "aiFigures": {"total_fee": "203 300 €", "client_name": "GREATLUCK INVESTIMENTOS IMOBILIARIOS LDA", "stage_count": "1", "project_name": "Travessa do Oleiro", "proposal_date": "11/11/2026", "proposal_number": "26117", "contact_salutation": "—", "estimated_duration": "43 semanas"}, "letterSettings": {"templates": {}, "signatoryName": "Luis Pedra Silva", "signatureData": "/__l5e/assets-v1/21490fcf-fd50-4c3a-93bd-3ff340f43065/luis-pedra-silva-signature.jpg"}, "pageBreakAfter": true, "pageBreakBefore": true}}, {"id": "cf14e2f3-7f6a-407c-957b-11e8a198d652", "title": "Descrição do Projeto", "sort_order": 70, "before": {"html": "<p>A nossa proposta refere-se à elaboração dos estudos e Projecto de Arquitectura e Assistência Técnica à execução da obra de alteração de um conjunto edificado, sito na Travessa do Oleiro, n.º 11 a 15, freguesia da Misericórdia, em Lisboa, para a instalação de apartamentos turísticos (serviced apartments).</p><p>A proposta apresentada assenta na seguinte informação sobre o edifício existente:</p><ul><li><p>Levantamento topográfico e perfil de frente de rua (Topomartins, desenho 3326TOP001, revisão A, julho de 2026);</p></li><li><p>Informação prestada pelo promotor;</p></li><li><p>Consulta ao portal LXi para tomar conhecimento das condicionantes urbanísticas do edifício;</p></li><li><p>Análise das condicionantes para estabelecer um cenário possível de intervenção e, com isso, a prestação de serviços necessária para o promotor.</p></li></ul><p>O lote, com uma área total de 384,30 m², tem frente para a Travessa do Oleiro, entre a Rua do Poço dos Negros e a Rua dos Poiais de São Bento, e é composto pelos seguintes elementos:</p><table style=\"min-width: 50px;\"><colgroup><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><th colspan=\"1\" rowspan=\"1\"><p>Elemento</p></th><th colspan=\"1\" rowspan=\"1\"><p>Área (m²)</p></th></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>A – Edifício principal, 5 pisos</p></td><td colspan=\"1\" rowspan=\"1\"><p>150,60</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>B – Anexo, 3 pisos</p></td><td colspan=\"1\" rowspan=\"1\"><p>19,10</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>C – Anexo, 2 pisos</p></td><td colspan=\"1\" rowspan=\"1\"><p>38,00</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>D – Anexo, 1 piso</p></td><td colspan=\"1\" rowspan=\"1\"><p>13,50</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>L1 – Logradouro</p></td><td colspan=\"1\" rowspan=\"1\"><p>36,10</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>L2 – Logradouro</p></td><td colspan=\"1\" rowspan=\"1\"><p>127,00</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><strong>Limite do lote – área total</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p><strong>384,30</strong></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>E – Área bruta privativa subterrânea</p></td><td colspan=\"1\" rowspan=\"1\"><p>32,70</p></td></tr></tbody></table><p>Com base nestes elementos, estimamos uma área bruta de construção existente de cerca de <strong>930 m²</strong> (edifício principal com cerca de 750 m² em 5 pisos, anexos e área subterrânea).</p><p>O terreno apresenta um desnível acentuado: a Travessa do Oleiro sobe da cota 12,15 (Rua do Poço dos Negros) até à cota 21,04 (Rua dos Poiais de São Bento). A fachada do edifício principal assenta entre as cotas 15,36 e 16,18 e o logradouro posterior (L2) situa-se aproximadamente à cota 19,6, cerca de 4 m acima da entrada pela Travessa do Oleiro.</p><p>Da análise do levantamento e das condicionantes do local, apresentamos uma proposta de prestação de serviços assente nas seguintes premissas:</p><ul><li><p>Demolição do interior do edifício existente e manutenção das fachadas principal e tardoz;</p></li><li><p>Reconversão do conjunto em apartamentos turísticos, a licenciar como empreendimento turístico nos termos do Regime Jurídico dos Empreendimentos Turísticos (Decreto-Lei n.º 39/2008, na sua redação atual);</p></li><li><p>O número e a tipologia das unidades de alojamento serão definidos na fase de Programa Base, em função das condicionantes urbanísticas, dos requisitos de classificação e do programa do promotor;</p></li><li><p>Estudo do aproveitamento dos anexos (B, C e D) e dos logradouros como áreas de apoio e espaços exteriores.</p></li></ul><p><strong>NOTA:</strong> As áreas indicadas resultam do levantamento topográfico e servem de orientação para a elaboração da proposta de honorários. As áreas brutas de construção existentes serão confirmadas com o levantamento arquitetónico do edifício.</p><p>Para além do projeto de Arquitetura e Plano de Acessibilidades, faz parte desta proposta:</p><ul><li><p>A coordenação dos diversos projetos de especialidades com o projeto de arquitetura;</p></li><li><p>A representação do requerente no portal Loja Lisboa e as submissões dos projetos no portal;</p></li><li><p>O acompanhamento do pedido de parecer ao Turismo de Portugal, I.P., quando aplicável ao licenciamento do empreendimento turístico.</p></li></ul><p></p>", "text": "A nossa proposta refere-se à elaboração dos estudos e Projecto de Arquitectura e Assistência Técnica à execução da obra de alteração de um conjunto edificado, sito na Travessa do Oleiro, n.º 11 a 15, freguesia da Misericórdia, em Lisboa, para a instalação de apartamentos turísticos (serviced apartments).\n\nA proposta apresentada assenta na seguinte informação sobre o edifício existente:\n\n\n\n\n\nLevantamento topográfico e perfil de frente de rua (Topomartins, desenho 3326TOP001, revisão A, julho de 2026);\n\n\n\nInformação prestada pelo promotor;\n\n\n\nConsulta ao portal LXi para tomar conhecimento das condicionantes urbanísticas do edifício;\n\n\n\nAnálise das condicionantes para estabelecer um cenário possível de intervenção e, com isso, a prestação de serviços necessária para o promotor.\n\nO lote, com uma área total de 384,30 m², tem frente para a Travessa do Oleiro, entre a Rua do Poço dos Negros e a Rua dos Poiais de São Bento, e é composto pelos seguintes elementos:\n\n\n\n\n\n\n\nElemento\n\n\n\nÁrea (m²)\n\n\n\n\n\nA – Edifício principal, 5 pisos\n\n\n\n150,60\n\n\n\n\n\nB – Anexo, 3 pisos\n\n\n\n19,10\n\n\n\n\n\nC – Anexo, 2 pisos\n\n\n\n38,00\n\n\n\n\n\nD – Anexo, 1 piso\n\n\n\n13,50\n\n\n\n\n\nL1 – Logradouro\n\n\n\n36,10\n\n\n\n\n\nL2 – Logradouro\n\n\n\n127,00\n\n\n\n\n\nLimite do lote – área total\n\n\n\n384,30\n\n\n\n\n\nE – Área bruta privativa subterrânea\n\n\n\n32,70\n\nCom base nestes elementos, estimamos uma área bruta de construção existente de cerca de 930 m² (edifício principal com cerca de 750 m² em 5 pisos, anexos e área subterrânea).\n\nO terreno apresenta um desnível acentuado: a Travessa do Oleiro sobe da cota 12,15 (Rua do Poço dos Negros) até à cota 21,04 (Rua dos Poiais de São Bento). A fachada do edifício principal assenta entre as cotas 15,36 e 16,18 e o logradouro posterior (L2) situa-se aproximadamente à cota 19,6, cerca de 4 m acima da entrada pela Travessa do Oleiro.\n\nDa análise do levantamento e das condicionantes do local, apresentamos uma proposta de prestação de serviços assente nas seguintes premissas:\n\n\n\n\n\nDemolição do interior do edifício existente e manutenção das fachadas principal e tardoz;\n\n\n\nReconversão do conjunto em apartamentos turísticos, a licenciar como empreendimento turístico nos termos do Regime Jurídico dos Empreendimentos Turísticos (Decreto-Lei n.º 39/2008, na sua redação atual);\n\n\n\nO número e a tipologia das unidades de alojamento serão definidos na fase de Programa Base, em função das condicionantes urbanísticas, dos requisitos de classificação e do programa do promotor;\n\n\n\nEstudo do aproveitamento dos anexos (B, C e D) e dos logradouros como áreas de apoio e espaços exteriores.\n\nNOTA: As áreas indicadas resultam do levantamento topográfico e servem de orientação para a elaboração da proposta de honorários. As áreas brutas de construção existentes serão confirmadas com o levantamento arquitetónico do edifício.\n\nPara além do projeto de Arquitetura e Plano de Acessibilidades, faz parte desta proposta:\n\n\n\n\n\nA coordenação dos diversos projetos de especialidades com o projeto de arquitetura;\n\n\n\nA representação do requerente no portal Loja Lisboa e as submissões dos projetos no portal;\n\n\n\nO acompanhamento do pedido de parecer ao Turismo de Portugal, I.P., quando aplicável ao licenciamento do empreendimento turístico.\n\n", "headingLevel": "h1", "pageBreakBefore": true}, "after": {"html": "<p>A nossa proposta refere-se à elaboração dos estudos e Projecto de Arquitectura e Assistência Técnica à execução da obra de alteração de um conjunto edificado, sito na Travessa do Oleiro, n.º 11 a 15, freguesia da Misericórdia, em Lisboa, para a instalação de apartamentos turísticos (serviced apartments).</p><p>A Pedra Silva Arquitectos (PSA) será a autora do projeto de arquitetura e a equipa projetista responsável pelo processo, trabalhando em parceria com o designer de interiores indicado pelo Cliente. A PSA irá integrar as soluções de interiores nos projetos de licenciamento e de execução e assegurar a coordenação geral das especialidades.</p><p>A proposta apresentada assenta na seguinte informação sobre o edifício existente:</p><ul><li><p>Levantamento topográfico e perfil de frente de rua (Topomartins, desenho 3326TOP001, revisão A, julho de 2026);</p></li><li><p>Informação prestada pelo promotor;</p></li><li><p>Conceito de design de interiores a fornecer pelo designer de interiores indicado pelo Cliente;</p></li><li><p>Consulta ao portal LXi para tomar conhecimento das condicionantes urbanísticas do edifício;</p></li><li><p>Análise das condicionantes para estabelecer um cenário possível de intervenção e, com isso, a prestação de serviços necessária para o promotor.</p></li></ul><p>O lote, com uma área total de 384,30 m², tem frente para a Travessa do Oleiro, entre a Rua do Poço dos Negros e a Rua dos Poiais de São Bento, e é composto pelos seguintes elementos:</p><table style=\"min-width: 50px;\"><colgroup><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><th colspan=\"1\" rowspan=\"1\"><p>Elemento</p></th><th colspan=\"1\" rowspan=\"1\"><p>Área (m²)</p></th></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>A – Edifício principal, 5 pisos</p></td><td colspan=\"1\" rowspan=\"1\"><p>150,60</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>B – Anexo, 3 pisos</p></td><td colspan=\"1\" rowspan=\"1\"><p>19,10</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>C – Anexo, 2 pisos</p></td><td colspan=\"1\" rowspan=\"1\"><p>38,00</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>D – Anexo, 1 piso</p></td><td colspan=\"1\" rowspan=\"1\"><p>13,50</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>L1 – Logradouro</p></td><td colspan=\"1\" rowspan=\"1\"><p>36,10</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>L2 – Logradouro</p></td><td colspan=\"1\" rowspan=\"1\"><p>127,00</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><strong>Limite do lote – área total</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p><strong>384,30</strong></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>E – Área bruta privativa subterrânea</p></td><td colspan=\"1\" rowspan=\"1\"><p>32,70</p></td></tr></tbody></table><p>Com base nestes elementos, estimamos uma área bruta de construção existente de cerca de <strong>930 m²</strong> (edifício principal com cerca de 750 m² em 5 pisos, anexos e área subterrânea).</p><p>O terreno apresenta um desnível acentuado: a Travessa do Oleiro sobe da cota 12,15 (Rua do Poço dos Negros) até à cota 21,04 (Rua dos Poiais de São Bento). A fachada do edifício principal assenta entre as cotas 15,36 e 16,18 e o logradouro posterior (L2) situa-se aproximadamente à cota 19,6, cerca de 4 m acima da entrada pela Travessa do Oleiro.</p><p>Da análise do levantamento e das condicionantes do local, apresentamos uma proposta de prestação de serviços assente nas seguintes premissas:</p><ul><li><p>Demolição do interior do edifício existente e manutenção das fachadas principal e tardoz;</p></li><li><p>Reconversão do conjunto em apartamentos turísticos, a licenciar como empreendimento turístico nos termos do Regime Jurídico dos Empreendimentos Turísticos (Decreto-Lei n.º 39/2008, na sua redação atual);</p></li><li><p>O número e a tipologia das unidades de alojamento serão definidos na fase de Programa Base, em função das condicionantes urbanísticas, dos requisitos de classificação e do programa do promotor, em articulação com o designer de interiores indicado pelo Cliente;</p></li><li><p>Estudo do aproveitamento dos anexos (B, C e D) e dos logradouros como áreas de apoio e espaços exteriores.</p></li></ul><p><strong>NOTA:</strong> As áreas indicadas resultam do levantamento topográfico e servem de orientação para a elaboração da proposta de honorários. As áreas brutas de construção existentes serão confirmadas com o levantamento arquitetónico do edifício.</p><p>Para além do projeto de Arquitetura e Plano de Acessibilidades, faz parte desta proposta:</p><ul><li><p>A coordenação dos diversos projetos de especialidades com o projeto de arquitetura;</p></li><li><p>A representação do requerente no portal Loja Lisboa e as submissões dos projetos no portal;</p></li><li><p>O acompanhamento do pedido de parecer ao Turismo de Portugal, I.P., quando aplicável ao licenciamento do empreendimento turístico.</p></li></ul><p></p><p>Em cada fase, a PSA só poderá desenvolver o seu trabalho após a receção dos elementos necessários por parte do Cliente e do designer de interiores. Caso estes elementos não sejam recebidos nos prazos acordados, a PSA não poderá ser responsabilizada por atrasos ou incumprimento de prazos.</p><p>Repartição de responsabilidades: a PSA é responsável pelo projeto de arquitetura do edifício, incluindo as áreas técnicas e de apoio, a integração das soluções de interiores nos projetos de licenciamento e de execução e a coordenação geral das especialidades; o designer de interiores indicado pelo Cliente é responsável pelo conceito e projeto de design de interiores dos apartamentos turísticos e das áreas comuns, incluindo mobiliário, equipamento e decoração (FF&amp;E) e iluminação decorativa. A fronteira detalhada entre os dois âmbitos será confirmada na fase de Programa.</p>", "text": "A nossa proposta refere-se à elaboração dos estudos e Projecto de Arquitectura e Assistência Técnica à execução da obra de alteração de um conjunto edificado, sito na Travessa do Oleiro, n.º 11 a 15, freguesia da Misericórdia, em Lisboa, para a instalação de apartamentos turísticos (serviced apartments).\nA Pedra Silva Arquitectos (PSA) será a autora do projeto de arquitetura e a equipa projetista responsável pelo processo, trabalhando em parceria com o designer de interiores indicado pelo Cliente. A PSA irá integrar as soluções de interiores nos projetos de licenciamento e de execução e assegurar a coordenação geral das especialidades.\nA proposta apresentada assenta na seguinte informação sobre o edifício existente:\nLevantamento topográfico e perfil de frente de rua (Topomartins, desenho 3326TOP001, revisão A, julho de 2026);\nInformação prestada pelo promotor;\nConceito de design de interiores a fornecer pelo designer de interiores indicado pelo Cliente;\nConsulta ao portal LXi para tomar conhecimento das condicionantes urbanísticas do edifício;\nAnálise das condicionantes para estabelecer um cenário possível de intervenção e, com isso, a prestação de serviços necessária para o promotor.\nO lote, com uma área total de 384,30 m², tem frente para a Travessa do Oleiro, entre a Rua do Poço dos Negros e a Rua dos Poiais de São Bento, e é composto pelos seguintes elementos:\nElemento\nÁrea (m²)\nA – Edifício principal, 5 pisos\n150,60\nB – Anexo, 3 pisos\n19,10\nC – Anexo, 2 pisos\n38,00\nD – Anexo, 1 piso\n13,50\nL1 – Logradouro\n36,10\nL2 – Logradouro\n127,00\nLimite do lote – área total\n384,30\nE – Área bruta privativa subterrânea\n32,70\nCom base nestes elementos, estimamos uma área bruta de construção existente de cerca de\n930 m²\n(edifício principal com cerca de 750 m² em 5 pisos, anexos e área subterrânea).\nO terreno apresenta um desnível acentuado: a Travessa do Oleiro sobe da cota 12,15 (Rua do Poço dos Negros) até à cota 21,04 (Rua dos Poiais de São Bento). A fachada do edifício principal assenta entre as cotas 15,36 e 16,18 e o logradouro posterior (L2) situa-se aproximadamente à cota 19,6, cerca de 4 m acima da entrada pela Travessa do Oleiro.\nDa análise do levantamento e das condicionantes do local, apresentamos uma proposta de prestação de serviços assente nas seguintes premissas:\nDemolição do interior do edifício existente e manutenção das fachadas principal e tardoz;\nReconversão do conjunto em apartamentos turísticos, a licenciar como empreendimento turístico nos termos do Regime Jurídico dos Empreendimentos Turísticos (Decreto-Lei n.º 39/2008, na sua redação atual);\nO número e a tipologia das unidades de alojamento serão definidos na fase de Programa Base, em função das condicionantes urbanísticas, dos requisitos de classificação e do programa do promotor, em articulação com o designer de interiores indicado pelo Cliente;\nEstudo do aproveitamento dos anexos (B, C e D) e dos logradouros como áreas de apoio e espaços exteriores.\nNOTA:\nAs áreas indicadas resultam do levantamento topográfico e servem de orientação para a elaboração da proposta de honorários. As áreas brutas de construção existentes serão confirmadas com o levantamento arquitetónico do edifício.\nPara além do projeto de Arquitetura e Plano de Acessibilidades, faz parte desta proposta:\nA coordenação dos diversos projetos de especialidades com o projeto de arquitetura;\nA representação do requerente no portal Loja Lisboa e as submissões dos projetos no portal;\nO acompanhamento do pedido de parecer ao Turismo de Portugal, I.P., quando aplicável ao licenciamento do empreendimento turístico.\nEm cada fase, a PSA só poderá desenvolver o seu trabalho após a receção dos elementos necessários por parte do Cliente e do designer de interiores. Caso estes elementos não sejam recebidos nos prazos acordados, a PSA não poderá ser responsabilizada por atrasos ou incumprimento de prazos.\nRepartição de responsabilidades: a PSA é responsável pelo projeto de arquitetura do edifício, incluindo as áreas técnicas e de apoio, a integração das soluções de interiores nos projetos de licenciamento e de execução e a coordenação geral das especialidades; o designer de interiores indicado pelo Cliente é responsável pelo conceito e projeto de design de interiores dos apartamentos turísticos e das áreas comuns, incluindo mobiliário, equipamento e decoração (FF&E) e iluminação decorativa. A fronteira detalhada entre os dois âmbitos será confirmada na fase de Programa.", "headingLevel": "h1", "pageBreakBefore": true}}, {"id": "216a1529-c8e2-42cd-acb0-5398f9a84b84", "title": "Programa", "sort_order": 90, "before": {"html": "<p></p>", "text": "", "client_info": "Levantamento arquitetónico do edifício (plantas, cortes e alçados), por técnico credenciado\nLevantamento dos alçados da frente de rua do quarteirão\nPrograma e objetivos do promotor, incluindo o modelo de exploração pretendido\nLimites orçamentais da obra\nDocumentação do imóvel (caderneta predial e certidão do registo predial)", "deliverables": "Programa Base do empreendimento (unidades de alojamento e áreas de apoio).\nSíntese das condicionantes urbanísticas e regulamentares.\nEstratégia de intervenção.", "headingLevel": "h2", "objective_html": "<p>Nest fase iremos reunir toda a informação do Cliente que possibilite compreender as suas intenções para o Projeto e toda a informação relevante para o seu desenvolvimento, tal como limitações ou restrições aplicáveis, entre elas as condicionantes urbanísticas, os requisitos de classificação do empreendimento turístico e os limites orçamentais.</p><p>Consiste em criar e desenvolver uma estratégia de intervenção e propor uma determinada abordagem arquitetónica, incluindo a definição preliminar do número e da tipologia das unidades de alojamento, de modo a cumprir com os seus objetivos.</p>", "objective_text": "Nest fase iremos reunir toda a informação do Cliente que possibilite compreender as suas intenções para o Projeto e toda a informação relevante para o seu desenvolvimento, tal como limitações ou restrições aplicáveis, entre elas as condicionantes urbanísticas, os requisitos de classificação do empreendimento turístico e os limites orçamentais.\n\nConsiste em criar e desenvolver uma estratégia de intervenção e propor uma determinada abordagem arquitetónica, incluindo a definição preliminar do número e da tipologia das unidades de alojamento, de modo a cumprir com os seus objetivos.", "key_activities_html": "<ul><li><p>Visita ao local / reunião com o cliente;</p></li><li><p>Consulta de elementos sobre o edifício (no arquivo municipal ou outros);</p></li><li><p>Consulta da legislação aplicável à intervenção, incluindo o regime jurídico dos empreendimentos turísticos e os respetivos requisitos de classificação;</p></li><li><p>Definição preliminar do programa: número, tipologia e áreas das unidades de alojamento e das áreas de apoio;</p></li><li><p>Eventual agendamento de reunião com a Câmara Municipal de Lisboa para esclarecimentos.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nVisita ao local / reunião com o cliente;\n\n\n\nConsulta de elementos sobre o edifício (no arquivo municipal ou outros);\n\n\n\nConsulta da legislação aplicável à intervenção, incluindo o regime jurídico dos empreendimentos turísticos e os respetivos requisitos de classificação;\n\n\n\nDefinição preliminar do programa: número, tipologia e áreas das unidades de alojamento e das áreas de apoio;\n\n\n\nEventual agendamento de reunião com a Câmara Municipal de Lisboa para esclarecimentos.\n\n", "stage_approval_html": "<p>No final desta fase, o cliente aprova o Programa Base, que servirá de referência para o desenvolvimento do Estudo Prévio.</p>", "stage_approval_text": "No final desta fase, o cliente aprova o Programa Base, que servirá de referência para o desenvolvimento do Estudo Prévio."}, "after": {"html": "<p></p>", "text": "", "client_info": "Levantamento arquitetónico do edifício (plantas, cortes e alçados), por técnico credenciado\nLevantamento dos alçados da frente de rua do quarteirão\nPrograma e objetivos do promotor, incluindo o modelo de exploração pretendido\nLimites orçamentais da obra\nDocumentação do imóvel (caderneta predial e certidão do registo predial)\nConceito e elementos de design de interiores a fornecer pelo designer de interiores indicado pelo Cliente, nos prazos acordados", "deliverables": "Programa Base do empreendimento (unidades de alojamento e áreas de apoio).\nSíntese das condicionantes urbanísticas e regulamentares.\nEstratégia de intervenção.", "headingLevel": "h2", "objective_html": "<p>O Programa faz parte desta prestação de serviços e é desenvolvido pela PSA em conjunto com o Cliente e o designer de interiores por ele indicado.</p><p>Nest fase iremos reunir toda a informação do Cliente que possibilite compreender as suas intenções para o Projeto e toda a informação relevante para o seu desenvolvimento, tal como limitações ou restrições aplicáveis, entre elas as condicionantes urbanísticas, os requisitos de classificação do empreendimento turístico e os limites orçamentais.</p><p>Consiste em criar e desenvolver uma estratégia de intervenção e propor uma determinada abordagem arquitetónica, incluindo a definição preliminar do número e da tipologia das unidades de alojamento, de modo a cumprir com os seus objetivos.</p>", "objective_text": "O Programa faz parte desta prestação de serviços e é desenvolvido pela PSA em conjunto com o Cliente e o designer de interiores por ele indicado.\nNest fase iremos reunir toda a informação do Cliente que possibilite compreender as suas intenções para o Projeto e toda a informação relevante para o seu desenvolvimento, tal como limitações ou restrições aplicáveis, entre elas as condicionantes urbanísticas, os requisitos de classificação do empreendimento turístico e os limites orçamentais.\nConsiste em criar e desenvolver uma estratégia de intervenção e propor uma determinada abordagem arquitetónica, incluindo a definição preliminar do número e da tipologia das unidades de alojamento, de modo a cumprir com os seus objetivos.", "key_activities_html": "<ul><li><p>Visita ao local / reunião com o Cliente e o designer de interiores indicado pelo Cliente;</p></li><li><p>Consulta de elementos sobre o edifício (no arquivo municipal ou outros);</p></li><li><p>Consulta da legislação aplicável à intervenção, incluindo o regime jurídico dos empreendimentos turísticos e os respetivos requisitos de classificação;</p></li><li><p>Definição preliminar do programa: número, tipologia e áreas das unidades de alojamento e das áreas de apoio;</p></li><li><p>Eventual agendamento de reunião com a Câmara Municipal de Lisboa para esclarecimentos.</p></li></ul><p></p>", "key_activities_text": "Visita ao local / reunião com o Cliente e o designer de interiores indicado pelo Cliente;\nConsulta de elementos sobre o edifício (no arquivo municipal ou outros);\nConsulta da legislação aplicável à intervenção, incluindo o regime jurídico dos empreendimentos turísticos e os respetivos requisitos de classificação;\nDefinição preliminar do programa: número, tipologia e áreas das unidades de alojamento e das áreas de apoio;\nEventual agendamento de reunião com a Câmara Municipal de Lisboa para esclarecimentos.", "stage_approval_html": "<p>No final desta fase, o cliente aprova o Programa Base, que servirá de referência para o desenvolvimento do Estudo Prévio.</p>", "stage_approval_text": "No final desta fase, o cliente aprova o Programa Base, que servirá de referência para o desenvolvimento do Estudo Prévio."}}, {"id": "d6c5bb08-ce52-4e08-815f-46ea4c6bf4db", "title": "Estudo Prévio", "sort_order": 100, "before": {"html": "<p></p>", "text": "", "client_info": "Topographic survey of the plot\nBudget indications, if available at this stage\nAny existing drawings and documentation provided by the Client\nObjectives and key features of the project\n", "deliverables": "Plantas, cortes e alçados do estudo prévio.\nQuadro de áreas e de unidades de alojamento.\nMemória descritiva sumária.\n6 imagens 3D (CGI) ilustrativas do conceito de arquitetura.", "headingLevel": "h2", "objective_html": "<p>Depois de definido e aprovado o Programa Base, vamos desenvolver os conceitos que foram definidos e apresentar soluções através de desenhos ou outros elementos que facilitem a sua compreensão do projeto, como a sua organização e a sua aparência final.</p><p>Iremos definir a globalidade da intervenção, de acordo com as suas pretensões para a otimização do edifício, dentro do contexto da legislação em vigor para o local, e estudar a melhor estratégia de encaminhar o processo para a obtenção da aprovação do licenciamento camarário.</p><p>É ainda nosso papel integrar o trabalho do Interior Design&nbsp; e  os projetistas das especialidades para, em conjunto com estes, estudar as soluções do ponto de vista técnico, construtivo e de custos.</p>", "objective_text": "Depois de definido e aprovado o Programa Base, vamos desenvolver os conceitos que foram definidos e apresentar soluções através de desenhos ou outros elementos que facilitem a sua compreensão do projeto, como a sua organização e a sua aparência final.\n\nIremos definir a globalidade da intervenção, de acordo com as suas pretensões para a otimização do edifício, dentro do contexto da legislação em vigor para o local, e estudar a melhor estratégia de encaminhar o processo para a obtenção da aprovação do licenciamento camarário.\n\nÉ ainda nosso papel integrar o trabalho do Interior Design  e  os projetistas das especialidades para, em conjunto com estes, estudar as soluções do ponto de vista técnico, construtivo e de custos.", "resources_visible": true, "client_info_visible": false, "key_activities_html": "<ul><li><p>Estudos do layout definitivo dos vários pisos e das unidades de alojamento;</p></li><li><p>Estudos de cortes e alçados;</p></li><li><p>Estudos de volumetria;</p></li><li><p>Estudos de materiais exteriores a usar;</p></li><li><p>Cálculo de áreas, cérceas e índices a cumprir;</p></li><li><p>Verificação preliminar dos requisitos de classificação aplicáveis aos apartamentos turísticos.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nEstudos do layout definitivo dos vários pisos e das unidades de alojamento;\n\n\n\nEstudos de cortes e alçados;\n\n\n\nEstudos de volumetria;\n\n\n\nEstudos de materiais exteriores a usar;\n\n\n\nCálculo de áreas, cérceas e índices a cumprir;\n\n\n\nVerificação preliminar dos requisitos de classificação aplicáveis aos apartamentos turísticos.\n\n", "stage_approval_html": "<p>Prevemos ir ao encontro dos seus objetivos através da apresentação de uma proposta de estudo prévio, desenvolvida durante o tempo estimado e com os recursos previstos no planeamento apresentado.</p><p>A nossa equipa fará as necessárias afinações na proposta de estudo prévio de forma a obter a sua total satisfação, desde que estas estejam dentro do número de horas previsto na nossa proposta de honorários.</p>", "stage_approval_text": "Prevemos ir ao encontro dos seus objetivos através da apresentação de uma proposta de estudo prévio, desenvolvida durante o tempo estimado e com os recursos previstos no planeamento apresentado.\n\nA nossa equipa fará as necessárias afinações na proposta de estudo prévio de forma a obter a sua total satisfação, desde que estas estejam dentro do número de horas previsto na nossa proposta de honorários."}, "after": {"html": "<p></p>", "text": "", "client_info": "Topographic survey of the plot\nBudget indications, if available at this stage\nAny existing drawings and documentation provided by the Client\nObjectives and key features of the project\n", "deliverables": "Plantas, cortes e alçados do estudo prévio.\nQuadro de áreas e de unidades de alojamento.\nMemória descritiva sumária.\n6 imagens 3D (CGI) ilustrativas do conceito de arquitetura.", "headingLevel": "h2", "objective_html": "<p>Depois de definido e aprovado o Programa Base, vamos desenvolver, em articulação com o designer de interiores indicado pelo Cliente, os conceitos que foram definidos e apresentar soluções através de desenhos ou outros elementos que facilitem a sua compreensão do projeto, como a sua organização e a sua aparência final.</p><p>Iremos definir a globalidade da intervenção, de acordo com as suas pretensões para a otimização do edifício, dentro do contexto da legislação em vigor para o local, e estudar a melhor estratégia de encaminhar o processo para a obtenção da aprovação do licenciamento camarário.</p><p>É ainda nosso papel integrar as soluções do designer de interiores indicado pelo Cliente no projeto de arquitetura e articular o trabalho dos projetistas das especialidades para, em conjunto com estes, estudar as soluções do ponto de vista técnico, construtivo e de custos.</p>", "objective_text": "Depois de definido e aprovado o Programa Base, vamos desenvolver, em articulação com o designer de interiores indicado pelo Cliente, os conceitos que foram definidos e apresentar soluções através de desenhos ou outros elementos que facilitem a sua compreensão do projeto, como a sua organização e a sua aparência final.\nIremos definir a globalidade da intervenção, de acordo com as suas pretensões para a otimização do edifício, dentro do contexto da legislação em vigor para o local, e estudar a melhor estratégia de encaminhar o processo para a obtenção da aprovação do licenciamento camarário.\nÉ ainda nosso papel integrar as soluções do designer de interiores indicado pelo Cliente no projeto de arquitetura e articular o trabalho dos projetistas das especialidades para, em conjunto com estes, estudar as soluções do ponto de vista técnico, construtivo e de custos.", "resources_visible": true, "client_info_visible": false, "key_activities_html": "<ul><li><p>Reunião inicial com o Cliente e o designer de interiores indicado pelo Cliente para confirmar o Programa e os objetivos do projeto;</p></li><li><p>Apresentação de toda a equipa do projeto, das especialidades ao design de interiores;</p></li><li><p>Estudos do layout definitivo dos vários pisos e das unidades de alojamento;</p></li><li><p>Estudos de cortes e alçados;</p></li><li><p>Estudos de volumetria;</p></li><li><p>Estudos de materiais exteriores a usar;</p></li><li><p>Cálculo de áreas, cérceas e índices a cumprir;</p></li><li><p>Verificação preliminar dos requisitos de classificação aplicáveis aos apartamentos turísticos.</p></li></ul><p></p>", "key_activities_text": "Reunião inicial com o Cliente e o designer de interiores indicado pelo Cliente para confirmar o Programa e os objetivos do projeto;\nApresentação de toda a equipa do projeto, das especialidades ao design de interiores;\nEstudos do layout definitivo dos vários pisos e das unidades de alojamento;\nEstudos de cortes e alçados;\nEstudos de volumetria;\nEstudos de materiais exteriores a usar;\nCálculo de áreas, cérceas e índices a cumprir;\nVerificação preliminar dos requisitos de classificação aplicáveis aos apartamentos turísticos.", "stage_approval_html": "<p>Prevemos ir ao encontro dos seus objetivos através da apresentação de uma proposta de estudo prévio, desenvolvida durante o tempo estimado e com os recursos previstos no planeamento apresentado.</p><p>A nossa equipa fará as necessárias afinações na proposta de estudo prévio de forma a obter a sua total satisfação, desde que estas estejam dentro do número de horas previsto na nossa proposta de honorários.</p>", "stage_approval_text": "Prevemos ir ao encontro dos seus objetivos através da apresentação de uma proposta de estudo prévio, desenvolvida durante o tempo estimado e com os recursos previstos no planeamento apresentado.\n\nA nossa equipa fará as necessárias afinações na proposta de estudo prévio de forma a obter a sua total satisfação, desde que estas estejam dentro do número de horas previsto na nossa proposta de honorários."}}, {"id": "201f0fcb-14e9-4488-b1de-76cbf1101ef3", "title": "Licenciamento", "sort_order": 120, "before": {"html": "<p></p>", "text": "", "client_info": "Aprovação do PIP pela Câmara Municipal de Lisboa\nProjetos de especialidades, a contratar pelo promotor\nEstudo geotécnico, se necessário", "deliverables": "Projeto de Arquitetura e Plano de Acessibilidades (peças escritas e desenhadas).\nProcesso de licenciamento submetido no portal Loja Lisboa.\nCoordenação dos projetos de especialidades para licenciamento.", "headingLevel": "h2", "objective_html": "<p>A fase de projeto de licenciamento consiste no desenvolvimento da proposta do PIP aprovado, através da interação com os projetistas de especialidades e da elaboração dos elementos solicitados pela Câmara Municipal para a instrução e submissão do processo, de acordo com a legislação aplicável, incluindo os requisitos aplicáveis aos empreendimentos turísticos.</p><p>Serão definidas nesta fase as soluções construtivas e será elaborado um estudo preliminar da integração das infraestruturas (gás, águas, esgotos, ventilação, eletricidade, telecomunicações) e, em especial, das estruturas e das condicionantes térmicas e acústicas na construção.</p><p>Definidas as soluções em conjunto com os projetistas de especialidades, serão feitos os necessários ajustes nos desenhos de arquitetura e preparados todos os elementos necessários (peças escritas, peças desenhadas e documentos) à submissão do processo de licenciamento no portal da Câmara Municipal de Lisboa.</p>", "objective_text": "A fase de projeto de licenciamento consiste no desenvolvimento da proposta do PIP aprovado, através da interação com os projetistas de especialidades e da elaboração dos elementos solicitados pela Câmara Municipal para a instrução e submissão do processo, de acordo com a legislação aplicável, incluindo os requisitos aplicáveis aos empreendimentos turísticos.\n\nSerão definidas nesta fase as soluções construtivas e será elaborado um estudo preliminar da integração das infraestruturas (gás, águas, esgotos, ventilação, eletricidade, telecomunicações) e, em especial, das estruturas e das condicionantes térmicas e acústicas na construção.\n\nDefinidas as soluções em conjunto com os projetistas de especialidades, serão feitos os necessários ajustes nos desenhos de arquitetura e preparados todos os elementos necessários (peças escritas, peças desenhadas e documentos) à submissão do processo de licenciamento no portal da Câmara Municipal de Lisboa.", "client_info_visible": true, "key_activities_html": "<ul><li><p>Definição de soluções construtivas e articulação das exigências das especialidades;</p></li><li><p>Verificação e coordenação dos elementos dos projetos de especialidades;</p></li><li><p>Projeto de Arquitetura e Plano de Acessibilidades – peças desenhadas e peças escritas em formato digital, a entregar na Câmara Municipal de Lisboa;</p></li><li><p>Submissão dos projetos na Câmara Municipal;</p></li><li><p>Acompanhamento do pedido de parecer ao Turismo de Portugal, I.P., quando aplicável;</p></li><li><p>Seguimento do processo na Câmara Municipal de Lisboa e resposta a eventuais notificações, desde que estas tenham sido motivadas por lapsos da equipa de projeto e não por opções de projeto impostas pelo dono de obra.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nDefinição de soluções construtivas e articulação das exigências das especialidades;\n\n\n\nVerificação e coordenação dos elementos dos projetos de especialidades;\n\n\n\nProjeto de Arquitetura e Plano de Acessibilidades – peças desenhadas e peças escritas em formato digital, a entregar na Câmara Municipal de Lisboa;\n\n\n\nSubmissão dos projetos na Câmara Municipal;\n\n\n\nAcompanhamento do pedido de parecer ao Turismo de Portugal, I.P., quando aplicável;\n\n\n\nSeguimento do processo na Câmara Municipal de Lisboa e resposta a eventuais notificações, desde que estas tenham sido motivadas por lapsos da equipa de projeto e não por opções de projeto impostas pelo dono de obra.\n\n", "stage_approval_html": "<p>A nossa proposta para a fase de licenciamento é apresentada considerando que a proposta de PIP é aprovada. Caso o licenciamento tenha de ser diferente da proposta apresentada como PIP e tenham de ser elaborados novos estudos, a nossa proposta de honorários e o calendário previsto terão de ser revistos.</p><p>Os serviços prestados pelos projetistas de especialidades não fazem parte desta proposta de honorários. Os projetos de especialidades são feitos por equipas externas à Pedra Silva Arquitectos e cada equipa apresenta o seu preço separadamente.</p>", "stage_approval_text": "A nossa proposta para a fase de licenciamento é apresentada considerando que a proposta de PIP é aprovada. Caso o licenciamento tenha de ser diferente da proposta apresentada como PIP e tenham de ser elaborados novos estudos, a nossa proposta de honorários e o calendário previsto terão de ser revistos.\n\nOs serviços prestados pelos projetistas de especialidades não fazem parte desta proposta de honorários. Os projetos de especialidades são feitos por equipas externas à Pedra Silva Arquitectos e cada equipa apresenta o seu preço separadamente."}, "after": {"html": "<p></p>", "text": "", "client_info": "Aprovação do PIP pela Câmara Municipal de Lisboa\nProjetos de especialidades, a contratar pelo promotor\nEstudo geotécnico, se necessário\nElementos do designer de interiores indicado pelo Cliente necessários à integração das soluções de interiores no licenciamento", "deliverables": "Projeto de Arquitetura e Plano de Acessibilidades (peças escritas e desenhadas).\nProcesso de licenciamento submetido no portal Loja Lisboa.\nCoordenação dos projetos de especialidades para licenciamento.", "headingLevel": "h2", "objective_html": "<p>A fase de projeto de licenciamento consiste no desenvolvimento da proposta do PIP aprovado, através da interação com o designer de interiores indicado pelo Cliente e com os projetistas de especialidades e da elaboração dos elementos solicitados pela Câmara Municipal para a instrução e submissão do processo, de acordo com a legislação aplicável, incluindo os requisitos aplicáveis aos empreendimentos turísticos.</p><p>Serão definidas nesta fase as soluções construtivas e será elaborado um estudo preliminar da integração das infraestruturas (gás, águas, esgotos, ventilação, eletricidade, telecomunicações) e, em especial, das estruturas e das condicionantes térmicas e acústicas na construção.</p><p>Definidas as soluções em conjunto com os projetistas de especialidades, serão feitos os necessários ajustes nos desenhos de arquitetura e preparados todos os elementos necessários (peças escritas, peças desenhadas e documentos) à submissão do processo de licenciamento no portal da Câmara Municipal de Lisboa.</p>", "objective_text": "A fase de projeto de licenciamento consiste no desenvolvimento da proposta do PIP aprovado, através da interação com o designer de interiores indicado pelo Cliente e com os projetistas de especialidades e da elaboração dos elementos solicitados pela Câmara Municipal para a instrução e submissão do processo, de acordo com a legislação aplicável, incluindo os requisitos aplicáveis aos empreendimentos turísticos.\nSerão definidas nesta fase as soluções construtivas e será elaborado um estudo preliminar da integração das infraestruturas (gás, águas, esgotos, ventilação, eletricidade, telecomunicações) e, em especial, das estruturas e das condicionantes térmicas e acústicas na construção.\nDefinidas as soluções em conjunto com os projetistas de especialidades, serão feitos os necessários ajustes nos desenhos de arquitetura e preparados todos os elementos necessários (peças escritas, peças desenhadas e documentos) à submissão do processo de licenciamento no portal da Câmara Municipal de Lisboa.", "client_info_visible": true, "key_activities_html": "<ul><li><p>Definição de soluções construtivas e articulação das exigências das especialidades;</p></li><li><p>Verificação e coordenação dos elementos dos projetos de especialidades;</p></li><li><p>Projeto de Arquitetura e Plano de Acessibilidades – peças desenhadas e peças escritas em formato digital, a entregar na Câmara Municipal de Lisboa;</p></li><li><p>Submissão dos projetos na Câmara Municipal;</p></li><li><p>Acompanhamento do pedido de parecer ao Turismo de Portugal, I.P., quando aplicável;</p></li><li><p>Seguimento do processo na Câmara Municipal de Lisboa e resposta a eventuais notificações, desde que estas tenham sido motivadas por lapsos da equipa de projeto e não por opções de projeto impostas pelo dono de obra.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nDefinição de soluções construtivas e articulação das exigências das especialidades;\n\n\n\nVerificação e coordenação dos elementos dos projetos de especialidades;\n\n\n\nProjeto de Arquitetura e Plano de Acessibilidades – peças desenhadas e peças escritas em formato digital, a entregar na Câmara Municipal de Lisboa;\n\n\n\nSubmissão dos projetos na Câmara Municipal;\n\n\n\nAcompanhamento do pedido de parecer ao Turismo de Portugal, I.P., quando aplicável;\n\n\n\nSeguimento do processo na Câmara Municipal de Lisboa e resposta a eventuais notificações, desde que estas tenham sido motivadas por lapsos da equipa de projeto e não por opções de projeto impostas pelo dono de obra.\n\n", "stage_approval_html": "<p>A nossa proposta para a fase de licenciamento é apresentada considerando que a proposta de PIP é aprovada. Caso o licenciamento tenha de ser diferente da proposta apresentada como PIP e tenham de ser elaborados novos estudos, a nossa proposta de honorários e o calendário previsto terão de ser revistos.</p><p>Os serviços prestados pelos projetistas de especialidades não fazem parte desta proposta de honorários. Os projetos de especialidades são feitos por equipas externas à Pedra Silva Arquitectos e cada equipa apresenta o seu preço separadamente.</p>", "stage_approval_text": "A nossa proposta para a fase de licenciamento é apresentada considerando que a proposta de PIP é aprovada. Caso o licenciamento tenha de ser diferente da proposta apresentada como PIP e tenham de ser elaborados novos estudos, a nossa proposta de honorários e o calendário previsto terão de ser revistos.\n\nOs serviços prestados pelos projetistas de especialidades não fazem parte desta proposta de honorários. Os projetos de especialidades são feitos por equipas externas à Pedra Silva Arquitectos e cada equipa apresenta o seu preço separadamente."}}, {"id": "1224bb85-cfe5-4a12-81cc-ed0279ba25cf", "title": "Projecto de Execução", "sort_order": 130, "before": {"html": "<p></p>", "text": "", "client_info": "Aprovação do Projeto de Licenciamento\nLimites do custo da obra\nDefinição dos equipamentos e do nível de acabamentos pretendidos para as unidades de alojamento", "deliverables": "Peças desenhadas do projeto de execução (escalas 1:50 e 1:20).\nDescrição de acabamentos e equipamentos.\nMapa de Quantidades e Medições.\nEstimativa Orçamental.\nCaderno de Encargos e Condições Técnicas Especiais.", "headingLevel": "h2", "objective_html": "<p>Esta fase consiste no desenvolvimento do projeto de arquitetura, em que iremos desenvolver soluções estéticas e construtivas de acordo com as suas intenções e com as condicionantes do Projeto, ditadas pela legislação em vigor, pelos condicionalismos técnicos e pelos limites do custo da obra.</p><p>Iremos elaborar desenhos e elementos escritos que irão especificar todos os materiais e trabalhos necessários para a execução da obra. Está previsto que haja repetição das soluções, acabamentos e equipamentos a definir para as unidades de alojamento.</p><p>A partir desses elementos é elaborado um Mapa de Quantidades e Medições, que lhe servirá de base para efetuar os pedidos de orçamento aos construtores, e uma Estimativa Orçamental, que irá usar como referência quando receber os orçamentos dos construtores. Faremos também a coordenação do projeto de Arquitetura com os diferentes projetos de especialidades.</p>", "objective_text": "Esta fase consiste no desenvolvimento do projeto de arquitetura, em que iremos desenvolver soluções estéticas e construtivas de acordo com as suas intenções e com as condicionantes do Projeto, ditadas pela legislação em vigor, pelos condicionalismos técnicos e pelos limites do custo da obra.\n\nIremos elaborar desenhos e elementos escritos que irão especificar todos os materiais e trabalhos necessários para a execução da obra. Está previsto que haja repetição das soluções, acabamentos e equipamentos a definir para as unidades de alojamento.\n\nA partir desses elementos é elaborado um Mapa de Quantidades e Medições, que lhe servirá de base para efetuar os pedidos de orçamento aos construtores, e uma Estimativa Orçamental, que irá usar como referência quando receber os orçamentos dos construtores. Faremos também a coordenação do projeto de Arquitetura com os diferentes projetos de especialidades.", "key_activities_html": "<ul><li><p>Plantas gerais – escala 1:50;</p></li><li><p>Plantas de pavimentos e acabamentos – escala 1:50;</p></li><li><p>Plantas de tetos, indicando materiais e pontos de iluminação – escala 1:50;</p></li><li><p>Cortes e alçados – escala 1:50;</p></li><li><p>Detalhes de zonas específicas, tais como instalações sanitárias, kitchenettes e outras áreas conforme necessário – escala 1:20;</p></li><li><p>Mapas de vãos e de mobiliário fixo – escala apropriada;</p></li><li><p>Conjunto de detalhes construtivos – escala apropriada;</p></li><li><p>Coordenação com os projetos de especialidades.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nPlantas gerais – escala 1:50;\n\n\n\nPlantas de pavimentos e acabamentos – escala 1:50;\n\n\n\nPlantas de tetos, indicando materiais e pontos de iluminação – escala 1:50;\n\n\n\nCortes e alçados – escala 1:50;\n\n\n\nDetalhes de zonas específicas, tais como instalações sanitárias, kitchenettes e outras áreas conforme necessário – escala 1:20;\n\n\n\nMapas de vãos e de mobiliário fixo – escala apropriada;\n\n\n\nConjunto de detalhes construtivos – escala apropriada;\n\n\n\nCoordenação com os projetos de especialidades.\n\n", "stage_approval_html": "<p><strong>NOTA:</strong> É importante facultar-nos informação quanto aos limites do custo da obra, de forma a tomar decisões de acordo com as condicionantes.</p>", "stage_approval_text": "NOTA: É importante facultar-nos informação quanto aos limites do custo da obra, de forma a tomar decisões de acordo com as condicionantes."}, "after": {"html": "<p></p>", "text": "", "client_info": "Aprovação do Projeto de Licenciamento\nLimites do custo da obra\nDefinição dos equipamentos e do nível de acabamentos pretendidos para as unidades de alojamento\nProjeto e especificações de interiores, incluindo acabamentos, equipamento e iluminação decorativa, a fornecer pelo designer de interiores indicado pelo Cliente", "deliverables": "Peças desenhadas do projeto de execução (escalas 1:50 e 1:20).\nDescrição de acabamentos e equipamentos.\nMapa de Quantidades e Medições.\nEstimativa Orçamental.\nCaderno de Encargos e Condições Técnicas Especiais.", "headingLevel": "h2", "objective_html": "<p>Esta fase consiste no desenvolvimento do projeto de arquitetura, em que iremos desenvolver soluções estéticas e construtivas de acordo com as intenções do promotor, as soluções do designer de interiores indicado pelo Cliente e as condicionantes do Projeto, ditadas pela legislação em vigor, pelos condicionalismos técnicos e pelos limites do custo da obra.</p><p>Iremos elaborar desenhos e elementos escritos que irão especificar todos os materiais e trabalhos necessários para a execução da obra. Está previsto que haja repetição das soluções, acabamentos e equipamentos a definir para as unidades de alojamento.</p><p>A partir desses elementos é elaborado um Mapa de Quantidades e Medições, que lhe servirá de base para efetuar os pedidos de orçamento aos construtores, e uma Estimativa Orçamental, que irá usar como referência quando receber os orçamentos dos construtores. Faremos também a integração das soluções do designer de interiores indicado pelo Cliente no projeto de Arquitetura e a coordenação com os diferentes projetos de especialidades.</p>", "objective_text": "Esta fase consiste no desenvolvimento do projeto de arquitetura, em que iremos desenvolver soluções estéticas e construtivas de acordo com as intenções do promotor, as soluções do designer de interiores indicado pelo Cliente e as condicionantes do Projeto, ditadas pela legislação em vigor, pelos condicionalismos técnicos e pelos limites do custo da obra.\nIremos elaborar desenhos e elementos escritos que irão especificar todos os materiais e trabalhos necessários para a execução da obra. Está previsto que haja repetição das soluções, acabamentos e equipamentos a definir para as unidades de alojamento.\nA partir desses elementos é elaborado um Mapa de Quantidades e Medições, que lhe servirá de base para efetuar os pedidos de orçamento aos construtores, e uma Estimativa Orçamental, que irá usar como referência quando receber os orçamentos dos construtores. Faremos também a integração das soluções do designer de interiores indicado pelo Cliente no projeto de Arquitetura e a coordenação com os diferentes projetos de especialidades.", "key_activities_html": "<ul><li><p>Plantas gerais – escala 1:50;</p></li><li><p>Plantas de pavimentos e acabamentos – escala 1:50;</p></li><li><p>Plantas de tetos, indicando materiais e pontos de iluminação – escala 1:50;</p></li><li><p>Cortes e alçados – escala 1:50;</p></li><li><p>Detalhes de zonas específicas, tais como instalações sanitárias, kitchenettes e outras áreas conforme necessário – escala 1:20;</p></li><li><p>Mapas de vãos e de mobiliário fixo – escala apropriada;</p></li><li><p>Conjunto de detalhes construtivos – escala apropriada;</p></li><li><p>Coordenação com os projetos de especialidades.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nPlantas gerais – escala 1:50;\n\n\n\nPlantas de pavimentos e acabamentos – escala 1:50;\n\n\n\nPlantas de tetos, indicando materiais e pontos de iluminação – escala 1:50;\n\n\n\nCortes e alçados – escala 1:50;\n\n\n\nDetalhes de zonas específicas, tais como instalações sanitárias, kitchenettes e outras áreas conforme necessário – escala 1:20;\n\n\n\nMapas de vãos e de mobiliário fixo – escala apropriada;\n\n\n\nConjunto de detalhes construtivos – escala apropriada;\n\n\n\nCoordenação com os projetos de especialidades.\n\n", "stage_approval_html": "<p><strong>NOTA:</strong> É importante facultar-nos informação quanto aos limites do custo da obra, de forma a tomar decisões de acordo com as condicionantes.</p>", "stage_approval_text": "NOTA: É importante facultar-nos informação quanto aos limites do custo da obra, de forma a tomar decisões de acordo com as condicionantes."}}, {"id": "ac887a66-f0dc-4341-b206-e08d36d49c1e", "title": "Avença fase de obra", "sort_order": 170, "before": {"html": "<p></p>", "text": "", "client_info": "Calendário da obra e identificação do Empreiteiro Geral e da Fiscalização\nPedidos de esclarecimento e de aprovação de materiais submetidos pelo empreiteiro", "deliverables": "Participação em 2 reuniões de obra por mês.\nRespostas a pedidos de esclarecimento do empreiteiro.\nPareceres sobre desenhos de preparação de obra e pedidos de aprovação de materiais.\nDesenhos complementares, quando necessário.", "headingLevel": "h2", "objective_html": "<p>Na fase de construção, faremos o acompanhamento da obra através de reuniões com o Empreiteiro Geral, a Fiscalização e os restantes técnicos responsáveis pelos projetos de especialidades, tendo como objetivo garantir a correta interpretação do projeto de Arquitetura e o esclarecimento de eventuais dúvidas.</p>", "objective_text": "Na fase de construção, faremos o acompanhamento da obra através de reuniões com o Empreiteiro Geral, a Fiscalização e os restantes técnicos responsáveis pelos projetos de especialidades, tendo como objetivo garantir a correta interpretação do projeto de Arquitetura e o esclarecimento de eventuais dúvidas.", "client_info_visible": true, "key_activities_html": "<ul><li><p>Reuniões na obra com o Empreiteiro Geral, a Fiscalização e os projetistas das especialidades (2 por mês);</p></li><li><p>Resposta a dúvidas do Empreiteiro Geral através de outras reuniões, telefonemas e emails, para além das reuniões de obra;</p></li><li><p>Análise e parecer de desenhos de preparação de obra relativos à arquitetura;</p></li><li><p>Análise e parecer de pedidos de aprovação de materiais e equipamentos relativos à arquitetura – exclusivamente os que forem alternativas ao definido em projeto devido a eventuais incompatibilidades na obra;</p></li><li><p>Desenhos ou outros elementos adicionais que esclareçam dúvidas ou omissões do projeto de execução.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nReuniões na obra com o Empreiteiro Geral, a Fiscalização e os projetistas das especialidades (2 por mês);\n\n\n\nResposta a dúvidas do Empreiteiro Geral através de outras reuniões, telefonemas e emails, para além das reuniões de obra;\n\n\n\nAnálise e parecer de desenhos de preparação de obra relativos à arquitetura;\n\n\n\nAnálise e parecer de pedidos de aprovação de materiais e equipamentos relativos à arquitetura – exclusivamente os que forem alternativas ao definido em projeto devido a eventuais incompatibilidades na obra;\n\n\n\nDesenhos ou outros elementos adicionais que esclareçam dúvidas ou omissões do projeto de execução.\n\n", "stage_approval_html": "<p><strong>NOTA:</strong> A Assistência Técnica não constitui uma Fiscalização da Obra, nem a Gestão da Obra. Em caso de suspensão, interrupção ou cancelamento da obra, não serão cobrados os honorários relativos à Assistência Técnica à Obra.</p>", "stage_approval_text": "NOTA: A Assistência Técnica não constitui uma Fiscalização da Obra, nem a Gestão da Obra. Em caso de suspensão, interrupção ou cancelamento da obra, não serão cobrados os honorários relativos à Assistência Técnica à Obra."}, "after": {"html": "<p></p>", "text": "", "client_info": "Calendário da obra e identificação do Empreiteiro Geral e da Fiscalização\nPedidos de esclarecimento e de aprovação de materiais submetidos pelo empreiteiro", "deliverables": "Participação em 2 reuniões de obra por mês.\nRespostas a pedidos de esclarecimento do empreiteiro.\nPareceres sobre desenhos de preparação de obra e pedidos de aprovação de materiais.\nDesenhos complementares, quando necessário.", "headingLevel": "h2", "objective_html": "<p>Na fase de construção, faremos o acompanhamento da obra através de reuniões com o Empreiteiro Geral, a Fiscalização, o designer de interiores indicado pelo Cliente e os restantes técnicos responsáveis pelos projetos de especialidades, tendo como objetivo garantir a correta interpretação do projeto de Arquitetura e o esclarecimento de eventuais dúvidas.</p>", "objective_text": "Na fase de construção, faremos o acompanhamento da obra através de reuniões com o Empreiteiro Geral, a Fiscalização, o designer de interiores indicado pelo Cliente e os restantes técnicos responsáveis pelos projetos de especialidades, tendo como objetivo garantir a correta interpretação do projeto de Arquitetura e o esclarecimento de eventuais dúvidas.", "client_info_visible": true, "key_activities_html": "<ul><li><p>Reuniões na obra com o Empreiteiro Geral, a Fiscalização, o designer de interiores indicado pelo Cliente e os projetistas das especialidades (2 por mês);</p></li><li><p>Resposta a dúvidas do Empreiteiro Geral através de outras reuniões, telefonemas e emails, para além das reuniões de obra;</p></li><li><p>Análise e parecer de desenhos de preparação de obra relativos à arquitetura;</p></li><li><p>Análise e parecer de pedidos de aprovação de materiais e equipamentos relativos à arquitetura – exclusivamente os que forem alternativas ao definido em projeto devido a eventuais incompatibilidades na obra;</p></li><li><p>Desenhos ou outros elementos adicionais que esclareçam dúvidas ou omissões do projeto de execução.</p></li></ul><p></p>", "key_activities_text": "Reuniões na obra com o Empreiteiro Geral, a Fiscalização, o designer de interiores indicado pelo Cliente e os projetistas das especialidades (2 por mês);\nResposta a dúvidas do Empreiteiro Geral através de outras reuniões, telefonemas e emails, para além das reuniões de obra;\nAnálise e parecer de desenhos de preparação de obra relativos à arquitetura;\nAnálise e parecer de pedidos de aprovação de materiais e equipamentos relativos à arquitetura – exclusivamente os que forem alternativas ao definido em projeto devido a eventuais incompatibilidades na obra;\nDesenhos ou outros elementos adicionais que esclareçam dúvidas ou omissões do projeto de execução.", "stage_approval_html": "<p><strong>NOTA:</strong> A Assistência Técnica não constitui uma Fiscalização da Obra, nem a Gestão da Obra. Em caso de suspensão, interrupção ou cancelamento da obra, não serão cobrados os honorários relativos à Assistência Técnica à Obra.</p>", "stage_approval_text": "NOTA: A Assistência Técnica não constitui uma Fiscalização da Obra, nem a Gestão da Obra. Em caso de suspensão, interrupção ou cancelamento da obra, não serão cobrados os honorários relativos à Assistência Técnica à Obra."}}, {"id": "e957cde6-7d52-4542-9d71-1d3b90ffea87", "title": "Considerações Gerais", "sort_order": 270, "before": {"html": "<p>A presente proposta baseia-se nos parâmetros e no âmbito do projeto aqui descritos e na informação disponível à data da sua elaboração. Alterações relevantes ao programa, às áreas, ao âmbito do projeto, aos requisitos legais ou às instruções do cliente poderão implicar a revisão do âmbito dos serviços e dos respetivos honorários.</p><h3>Cessação do contrato</h3><p>O cliente poderá cessar o contrato em qualquer fase de projeto com a antecedência devida de 20 dias úteis, ficando responsável por pagar a totalidade da fase que estiver a decorrer.</p><h3>Suspensão do contrato</h3><p>Na eventualidade de ser necessário suspender o contrato por tempo indeterminado, por razões fora do controlo da equipa projetista, será cobrado um valor mensal de standby equivalente a 50% do valor das mensalidades do contrato.</p><p>As Medições e o Mapa de Quantidades do projeto de arquitetura, elaborados na fase de Projeto de Execução, estão incluídos nesta proposta. Este ponto prevalece sobre a exclusão de medições prevista no artigo 2.5 dos Termos Gerais.</p>", "text": "A presente proposta baseia-se nos parâmetros e no âmbito do projeto aqui descritos e na informação disponível à data da sua elaboração. Alterações relevantes ao programa, às áreas, ao âmbito do projeto, aos requisitos legais ou às instruções do cliente poderão implicar a revisão do âmbito dos serviços e dos respetivos honorários.\n\nCessação do contrato\n\nO cliente poderá cessar o contrato em qualquer fase de projeto com a antecedência devida de 20 dias úteis, ficando responsável por pagar a totalidade da fase que estiver a decorrer.\n\nSuspensão do contrato\n\nNa eventualidade de ser necessário suspender o contrato por tempo indeterminado, por razões fora do controlo da equipa projetista, será cobrado um valor mensal de standby equivalente a 50% do valor das mensalidades do contrato.\n\nAs Medições e o Mapa de Quantidades do projeto de arquitetura, elaborados na fase de Projeto de Execução, estão incluídos nesta proposta. Este ponto prevalece sobre a exclusão de medições prevista no artigo 2.5 dos Termos Gerais.", "headingLevel": "h1"}, "after": {"html": "<p>A presente proposta baseia-se nos parâmetros e no âmbito do projeto aqui descritos e na informação disponível à data da sua elaboração. Alterações relevantes ao programa, às áreas, ao âmbito do projeto, aos requisitos legais ou às instruções do cliente poderão implicar a revisão do âmbito dos serviços e dos respetivos honorários.</p><h3>Cessação do contrato</h3><p>O cliente poderá cessar o contrato em qualquer fase de projeto com a antecedência devida de 20 dias úteis, ficando responsável por pagar a totalidade da fase que estiver a decorrer.</p><h3>Suspensão do contrato</h3><p>Na eventualidade de ser necessário suspender o contrato por tempo indeterminado, por razões fora do controlo da equipa projetista, será cobrado um valor mensal de standby equivalente a 50% do valor das mensalidades do contrato.</p><p>As Medições e o Mapa de Quantidades do projeto de arquitetura, elaborados na fase de Projeto de Execução, estão incluídos nesta proposta. Este ponto prevalece sobre a exclusão de medições prevista no artigo 2.5 dos Termos Gerais.</p><p>A PSA é a autora e coordenadora do projeto de arquitetura, em parceria com o designer de interiores indicado pelo Cliente. O cumprimento dos prazos de cada fase depende da receção atempada dos elementos a fornecer pelo Cliente e pelo designer de interiores.</p>", "text": "A presente proposta baseia-se nos parâmetros e no âmbito do projeto aqui descritos e na informação disponível à data da sua elaboração. Alterações relevantes ao programa, às áreas, ao âmbito do projeto, aos requisitos legais ou às instruções do cliente poderão implicar a revisão do âmbito dos serviços e dos respetivos honorários.\nCessação do contrato\nO cliente poderá cessar o contrato em qualquer fase de projeto com a antecedência devida de 20 dias úteis, ficando responsável por pagar a totalidade da fase que estiver a decorrer.\nSuspensão do contrato\nNa eventualidade de ser necessário suspender o contrato por tempo indeterminado, por razões fora do controlo da equipa projetista, será cobrado um valor mensal de standby equivalente a 50% do valor das mensalidades do contrato.\nAs Medições e o Mapa de Quantidades do projeto de arquitetura, elaborados na fase de Projeto de Execução, estão incluídos nesta proposta. Este ponto prevalece sobre a exclusão de medições prevista no artigo 2.5 dos Termos Gerais.\nA PSA é a autora e coordenadora do projeto de arquitetura, em parceria com o designer de interiores indicado pelo Cliente. O cumprimento dos prazos de cada fase depende da receção atempada dos elementos a fornecer pelo Cliente e pelo designer de interiores.", "headingLevel": "h1"}}, {"id": "c86dcb13-3ba9-414b-9eac-359b0a165f6a", "title": "Exclusões", "sort_order": 280, "before": {"html": "<p>Estão excluídos da proposta:</p><ul><li><p>IVA à taxa legal em vigor;</p></li><li><p>Despesas de deslocação, como viagens, alojamento, refeições e despesas diversas associadas, fora do concelho de Lisboa, que não estejam contempladas no capítulo da Assistência Técnica;</p></li><li><p>Todos os serviços especializados necessários ao desenvolvimento do projeto, como levantamentos topográficos e arquitetónicos, estudos geotécnicos e geológicos, etc.;</p></li><li><p>Taxas camarárias e taxas de outras entidades;</p></li><li><p>Projetos de especialidades e de paisagismo;</p></li><li><p>Preparação e lançamento de concurso de empreitadas;</p></li><li><p>Direção técnica da obra, administração da obra, coordenação e fiscalização da obra;</p></li><li><p>Elaboração de desenhos de preparação de obra;</p></li><li><p>Maquetes profissionais;</p></li><li><p>Imagens 3D para além das 6 incluídas no Estudo prévio;</p></li><li><p>Projeto de decoração de interiores e de mobiliário, equipamento e decoração (FF&amp;E), salvo se contratado como serviço opcional;</p></li><li><p>Projetos especiais (cozinhas técnicas, piscinas e spa);</p></li><li><p>Pedidos ou negociações para a obtenção de financiamentos (privados ou corporate);</p></li><li><p>Processo de classificação do empreendimento turístico junto do Turismo de Portugal após a conclusão da obra, e registo ou autorização de exploração;</p></li><li><p>Certificação energética e acústica.</p></li></ul><p></p>", "text": "Estão excluídos da proposta:\n\n\n\n\n\nIVA à taxa legal em vigor;\n\n\n\nDespesas de deslocação, como viagens, alojamento, refeições e despesas diversas associadas, fora do concelho de Lisboa, que não estejam contempladas no capítulo da Assistência Técnica;\n\n\n\nTodos os serviços especializados necessários ao desenvolvimento do projeto, como levantamentos topográficos e arquitetónicos, estudos geotécnicos e geológicos, etc.;\n\n\n\nTaxas camarárias e taxas de outras entidades;\n\n\n\nProjetos de especialidades e de paisagismo;\n\n\n\nPreparação e lançamento de concurso de empreitadas;\n\n\n\nDireção técnica da obra, administração da obra, coordenação e fiscalização da obra;\n\n\n\nElaboração de desenhos de preparação de obra;\n\n\n\nMaquetes profissionais;\n\n\n\nImagens 3D para além das 6 incluídas no Estudo prévio;\n\n\n\nProjeto de decoração de interiores e de mobiliário, equipamento e decoração (FF&E), salvo se contratado como serviço opcional;\n\n\n\nProjetos especiais (cozinhas técnicas, piscinas e spa);\n\n\n\nPedidos ou negociações para a obtenção de financiamentos (privados ou corporate);\n\n\n\nProcesso de classificação do empreendimento turístico junto do Turismo de Portugal após a conclusão da obra, e registo ou autorização de exploração;\n\n\n\nCertificação energética e acústica.\n\n", "headingLevel": "h1"}, "after": {"html": "<p>Estão excluídos da proposta:</p><ul><li><p>IVA à taxa legal em vigor;</p></li><li><p>Despesas de deslocação, como viagens, alojamento, refeições e despesas diversas associadas, fora do concelho de Lisboa, que não estejam contempladas no capítulo da Assistência Técnica;</p></li><li><p>Todos os serviços especializados necessários ao desenvolvimento do projeto, como levantamentos topográficos e arquitetónicos, estudos geotécnicos e geológicos, etc.;</p></li><li><p>Taxas camarárias e taxas de outras entidades;</p></li><li><p>Projetos de especialidades e de paisagismo;</p></li><li><p>Preparação e lançamento de concurso de empreitadas;</p></li><li><p>Direção técnica da obra, administração da obra, coordenação e fiscalização da obra;</p></li><li><p>Elaboração de desenhos de preparação de obra;</p></li><li><p>Maquetes profissionais;</p></li><li><p>Imagens 3D para além das 6 incluídas no Estudo prévio;</p></li><li><p>Projeto de design de interiores, incluindo mobiliário, equipamento e decoração (FF&amp;E), a cargo do designer de interiores indicado pelo Cliente;</p></li><li><p>Projetos especiais (cozinhas técnicas, piscinas e spa);</p></li><li><p>Pedidos ou negociações para a obtenção de financiamentos (privados ou corporate);</p></li><li><p>Processo de classificação do empreendimento turístico junto do Turismo de Portugal após a conclusão da obra, e registo ou autorização de exploração;</p></li><li><p>Certificação energética e acústica.</p></li></ul><p></p>", "text": "Estão excluídos da proposta:\nIVA à taxa legal em vigor;\nDespesas de deslocação, como viagens, alojamento, refeições e despesas diversas associadas, fora do concelho de Lisboa, que não estejam contempladas no capítulo da Assistência Técnica;\nTodos os serviços especializados necessários ao desenvolvimento do projeto, como levantamentos topográficos e arquitetónicos, estudos geotécnicos e geológicos, etc.;\nTaxas camarárias e taxas de outras entidades;\nProjetos de especialidades e de paisagismo;\nPreparação e lançamento de concurso de empreitadas;\nDireção técnica da obra, administração da obra, coordenação e fiscalização da obra;\nElaboração de desenhos de preparação de obra;\nMaquetes profissionais;\nImagens 3D para além das 6 incluídas no Estudo prévio;\nProjeto de design de interiores, incluindo mobiliário, equipamento e decoração (FF&E), a cargo do designer de interiores indicado pelo Cliente;\nProjetos especiais (cozinhas técnicas, piscinas e spa);\nPedidos ou negociações para a obtenção de financiamentos (privados ou corporate);\nProcesso de classificação do empreendimento turístico junto do Turismo de Portugal após a conclusão da obra, e registo ou autorização de exploração;\nCertificação energética e acústica.", "headingLevel": "h1"}}, {"id": "9569d0f6-2311-45bf-9656-86fd64ab7d2e", "title": "Serviço opcional – Design de Interiores", "sort_order": 260, "before": {"scope_html": "<ul><li><p>Conceito de design de interiores;</p></li><li><p>Seleção de materiais e acabamentos;</p></li><li><p>Desenhos gerais de interiores;</p></li><li><p>Projeto de mobiliário fixo e carpintarias;</p></li><li><p>Projeto das instalações sanitárias;</p></li><li><p>Coordenação de mobiliário, equipamento e decoração (FF&amp;E);</p></li><li><p>Coordenação da iluminação;</p></li><li><p>Especificações de interiores;</p></li><li><p>Documentação para concurso;</p></li><li><p>Assistência técnica à obra.</p></li></ul><p></p>", "scope_text": "\n\n\n\nConceito de design de interiores;\n\n\n\nSeleção de materiais e acabamentos;\n\n\n\nDesenhos gerais de interiores;\n\n\n\nProjeto de mobiliário fixo e carpintarias;\n\n\n\nProjeto das instalações sanitárias;\n\n\n\nCoordenação de mobiliário, equipamento e decoração (FF&E);\n\n\n\nCoordenação da iluminação;\n\n\n\nEspecificações de interiores;\n\n\n\nDocumentação para concurso;\n\n\n\nAssistência técnica à obra.\n\n", "headingLevel": "h1", "objective_html": "<p>A Pedra Silva Arquitectos disponibiliza um serviço integrado de Design de Interiores, que desenvolve a experiência do hóspede nas unidades de alojamento e nas áreas comuns, para além do projeto de arquitetura.</p><p>O trabalho desenvolvido pela mesma equipa multidisciplinar assegura a continuidade entre o conceito arquitetónico e o ambiente interior, permitindo coordenar as decisões de design desde as primeiras fases do projeto. Os honorários deste serviço serão apresentados mediante pedido do cliente.</p>", "objective_text": "A Pedra Silva Arquitectos disponibiliza um serviço integrado de Design de Interiores, que desenvolve a experiência do hóspede nas unidades de alojamento e nas áreas comuns, para além do projeto de arquitetura.\n\nO trabalho desenvolvido pela mesma equipa multidisciplinar assegura a continuidade entre o conceito arquitetónico e o ambiente interior, permitindo coordenar as decisões de design desde as primeiras fases do projeto. Os honorários deste serviço serão apresentados mediante pedido do cliente."}, "after": {"scope_html": "<ul><li><p>Conceito de design de interiores;</p></li><li><p>Seleção de materiais e acabamentos;</p></li><li><p>Desenhos gerais de interiores;</p></li><li><p>Projeto de mobiliário fixo e carpintarias;</p></li><li><p>Projeto das instalações sanitárias;</p></li><li><p>Coordenação de mobiliário, equipamento e decoração (FF&amp;E);</p></li><li><p>Coordenação da iluminação;</p></li><li><p>Especificações de interiores;</p></li><li><p>Documentação para concurso;</p></li><li><p>Assistência técnica à obra.</p></li></ul><p></p>", "scope_text": "\n\n\n\nConceito de design de interiores;\n\n\n\nSeleção de materiais e acabamentos;\n\n\n\nDesenhos gerais de interiores;\n\n\n\nProjeto de mobiliário fixo e carpintarias;\n\n\n\nProjeto das instalações sanitárias;\n\n\n\nCoordenação de mobiliário, equipamento e decoração (FF&E);\n\n\n\nCoordenação da iluminação;\n\n\n\nEspecificações de interiores;\n\n\n\nDocumentação para concurso;\n\n\n\nAssistência técnica à obra.\n\n", "headingLevel": "h1", "objective_html": "<p>A Pedra Silva Arquitectos disponibiliza um serviço integrado de Design de Interiores, que desenvolve a experiência do hóspede nas unidades de alojamento e nas áreas comuns, para além do projeto de arquitetura.</p><p>O trabalho desenvolvido pela mesma equipa multidisciplinar assegura a continuidade entre o conceito arquitetónico e o ambiente interior, permitindo coordenar as decisões de design desde as primeiras fases do projeto. Os honorários deste serviço serão apresentados mediante pedido do cliente.</p>", "objective_text": "A Pedra Silva Arquitectos disponibiliza um serviço integrado de Design de Interiores, que desenvolve a experiência do hóspede nas unidades de alojamento e nas áreas comuns, para além do projeto de arquitetura.\n\nO trabalho desenvolvido pela mesma equipa multidisciplinar assegura a continuidade entre o conceito arquitetónico e o ambiente interior, permitindo coordenar as decisões de design desde as primeiras fases do projeto. Os honorários deste serviço serão apresentados mediante pedido do cliente.", "html": "<p>Nesta proposta, o conceito e o projeto de design de interiores são da responsabilidade do designer de interiores indicado pelo Cliente. A PSA integra as suas soluções no projeto de arquitetura e assegura a articulação com as especialidades; esta integração está incluída no âmbito de arquitetura e não corresponde à prestação do serviço opcional de design de interiores. Qualquer contratação adicional de design de interiores à PSA dependerá de acordo separado e não substitui o âmbito do designer indicado pelo Cliente.</p>"}}]$changes$::jsonb) LOOP
IF NOT EXISTS(SELECT 1 FROM public.psa_proposal_blocks WHERE id=(c->>'id')::uuid AND content_rich=c->'before') THEN RAISE EXCEPTION 'Oleiro edited concurrently: %',c->>'title'; END IF;
END LOOP;
n:=public.clone_fee_proposal_as_revision_impl(src);
SELECT id INTO np FROM public.psa_proposals WHERE quote_id=n;
IF np IS NULL THEN RAISE EXCEPTION 'New revision has no document'; END IF;
UPDATE public.fee_proposals SET main_proposal_id=np,fee_source_mode=(SELECT fee_source_mode FROM public.fee_proposals WHERE id=src) WHERE id=n;
-- Source-preserving copying: match the exact order and name; the existing revision function maps parents and dependencies.
UPDATE public.quote_stages ns SET sale_source=os.sale_source,is_optional=os.is_optional,archived_at=os.archived_at,date_mode=os.date_mode FROM public.quote_stages os WHERE ns.quote_id=n AND os.quote_id=src AND ns.sort_order=os.sort_order AND ns.name=os.name;
FOR c IN SELECT value FROM jsonb_array_elements($changes$[{"id": "36752430-456a-4072-90d1-5721c6b37570", "title": "Carta", "sort_order": 20, "before": {"html": "<p>Agradecemos a oportunidade de apresentar a nossa proposta de serviços de arquitectura para {{project_name}}.</p><p>O âmbito proposto abrange o programa, o estudo prévio, o anteprojecto e a submissão do pedido de informação prévia, o licenciamento e o projecto de execução, bem como o apoio ao concurso de construção e o acompanhamento da fase de obra em regime de avença.</p><p>A proposta organiza-se em {{stage_count}} fases, com honorários totais de {{total_fee}} e uma duração estimada de {{estimated_duration}} a partir do início dos trabalhos, dependente da articulação entre os intervenientes e dos prazos de apreciação pelas entidades competentes.</p><p>Ficamos à disposição para esclarecer a proposta e ajustar a sua articulação às vossas necessidades. Será um gosto colaborar convosco.</p>", "aiFigures": {"total_fee": "203 300 €", "client_name": "GREATLUCK INVESTIMENTOS IMOBILIARIOS LDA", "stage_count": "1", "project_name": "Travessa do Oleiro", "proposal_date": "11/11/2026", "proposal_number": "26117", "contact_salutation": "—", "estimated_duration": "43 semanas"}, "letterSettings": {"templates": {}, "signatoryName": "Luis Pedra Silva", "signatureData": "/__l5e/assets-v1/21490fcf-fd50-4c3a-93bd-3ff340f43065/luis-pedra-silva-signature.jpg"}, "pageBreakAfter": true, "pageBreakBefore": true}, "after": {"html": "<p>Agradecemos a oportunidade de apresentar a nossa proposta de serviços de arquitectura para {{project_name}}.</p><p>A PSA será a autora do projeto de arquitetura, trabalhando em parceria com o designer de interiores indicado pelo Cliente e integrando as suas soluções nos projetos de licenciamento e de execução. O âmbito proposto abrange o programa, o estudo prévio, o anteprojecto e a submissão do pedido de informação prévia, o licenciamento e o projecto de execução, bem como o apoio ao concurso de construção e o acompanhamento da fase de obra em regime de avença.</p><p>A proposta organiza-se em {{stage_count}} fases, com honorários totais de {{total_fee}} e uma duração estimada de {{estimated_duration}} a partir do início dos trabalhos, dependente da articulação entre os intervenientes e dos prazos de apreciação pelas entidades competentes.</p><p>O desenvolvimento de cada fase depende da receção atempada dos elementos do Cliente e do designer de interiores. O projeto de design de interiores, incluindo mobiliário, equipamento e decoração (FF&amp;E), é da responsabilidade do designer de interiores indicado pelo Cliente e está excluído dos serviços da PSA. Ficamos à disposição para esclarecer a proposta e ajustar a sua articulação às vossas necessidades. Será um gosto colaborar convosco.</p>", "aiFigures": {"total_fee": "203 300 €", "client_name": "GREATLUCK INVESTIMENTOS IMOBILIARIOS LDA", "stage_count": "1", "project_name": "Travessa do Oleiro", "proposal_date": "11/11/2026", "proposal_number": "26117", "contact_salutation": "—", "estimated_duration": "43 semanas"}, "letterSettings": {"templates": {}, "signatoryName": "Luis Pedra Silva", "signatureData": "/__l5e/assets-v1/21490fcf-fd50-4c3a-93bd-3ff340f43065/luis-pedra-silva-signature.jpg"}, "pageBreakAfter": true, "pageBreakBefore": true}}, {"id": "cf14e2f3-7f6a-407c-957b-11e8a198d652", "title": "Descrição do Projeto", "sort_order": 70, "before": {"html": "<p>A nossa proposta refere-se à elaboração dos estudos e Projecto de Arquitectura e Assistência Técnica à execução da obra de alteração de um conjunto edificado, sito na Travessa do Oleiro, n.º 11 a 15, freguesia da Misericórdia, em Lisboa, para a instalação de apartamentos turísticos (serviced apartments).</p><p>A proposta apresentada assenta na seguinte informação sobre o edifício existente:</p><ul><li><p>Levantamento topográfico e perfil de frente de rua (Topomartins, desenho 3326TOP001, revisão A, julho de 2026);</p></li><li><p>Informação prestada pelo promotor;</p></li><li><p>Consulta ao portal LXi para tomar conhecimento das condicionantes urbanísticas do edifício;</p></li><li><p>Análise das condicionantes para estabelecer um cenário possível de intervenção e, com isso, a prestação de serviços necessária para o promotor.</p></li></ul><p>O lote, com uma área total de 384,30 m², tem frente para a Travessa do Oleiro, entre a Rua do Poço dos Negros e a Rua dos Poiais de São Bento, e é composto pelos seguintes elementos:</p><table style=\"min-width: 50px;\"><colgroup><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><th colspan=\"1\" rowspan=\"1\"><p>Elemento</p></th><th colspan=\"1\" rowspan=\"1\"><p>Área (m²)</p></th></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>A – Edifício principal, 5 pisos</p></td><td colspan=\"1\" rowspan=\"1\"><p>150,60</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>B – Anexo, 3 pisos</p></td><td colspan=\"1\" rowspan=\"1\"><p>19,10</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>C – Anexo, 2 pisos</p></td><td colspan=\"1\" rowspan=\"1\"><p>38,00</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>D – Anexo, 1 piso</p></td><td colspan=\"1\" rowspan=\"1\"><p>13,50</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>L1 – Logradouro</p></td><td colspan=\"1\" rowspan=\"1\"><p>36,10</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>L2 – Logradouro</p></td><td colspan=\"1\" rowspan=\"1\"><p>127,00</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><strong>Limite do lote – área total</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p><strong>384,30</strong></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>E – Área bruta privativa subterrânea</p></td><td colspan=\"1\" rowspan=\"1\"><p>32,70</p></td></tr></tbody></table><p>Com base nestes elementos, estimamos uma área bruta de construção existente de cerca de <strong>930 m²</strong> (edifício principal com cerca de 750 m² em 5 pisos, anexos e área subterrânea).</p><p>O terreno apresenta um desnível acentuado: a Travessa do Oleiro sobe da cota 12,15 (Rua do Poço dos Negros) até à cota 21,04 (Rua dos Poiais de São Bento). A fachada do edifício principal assenta entre as cotas 15,36 e 16,18 e o logradouro posterior (L2) situa-se aproximadamente à cota 19,6, cerca de 4 m acima da entrada pela Travessa do Oleiro.</p><p>Da análise do levantamento e das condicionantes do local, apresentamos uma proposta de prestação de serviços assente nas seguintes premissas:</p><ul><li><p>Demolição do interior do edifício existente e manutenção das fachadas principal e tardoz;</p></li><li><p>Reconversão do conjunto em apartamentos turísticos, a licenciar como empreendimento turístico nos termos do Regime Jurídico dos Empreendimentos Turísticos (Decreto-Lei n.º 39/2008, na sua redação atual);</p></li><li><p>O número e a tipologia das unidades de alojamento serão definidos na fase de Programa Base, em função das condicionantes urbanísticas, dos requisitos de classificação e do programa do promotor;</p></li><li><p>Estudo do aproveitamento dos anexos (B, C e D) e dos logradouros como áreas de apoio e espaços exteriores.</p></li></ul><p><strong>NOTA:</strong> As áreas indicadas resultam do levantamento topográfico e servem de orientação para a elaboração da proposta de honorários. As áreas brutas de construção existentes serão confirmadas com o levantamento arquitetónico do edifício.</p><p>Para além do projeto de Arquitetura e Plano de Acessibilidades, faz parte desta proposta:</p><ul><li><p>A coordenação dos diversos projetos de especialidades com o projeto de arquitetura;</p></li><li><p>A representação do requerente no portal Loja Lisboa e as submissões dos projetos no portal;</p></li><li><p>O acompanhamento do pedido de parecer ao Turismo de Portugal, I.P., quando aplicável ao licenciamento do empreendimento turístico.</p></li></ul><p></p>", "text": "A nossa proposta refere-se à elaboração dos estudos e Projecto de Arquitectura e Assistência Técnica à execução da obra de alteração de um conjunto edificado, sito na Travessa do Oleiro, n.º 11 a 15, freguesia da Misericórdia, em Lisboa, para a instalação de apartamentos turísticos (serviced apartments).\n\nA proposta apresentada assenta na seguinte informação sobre o edifício existente:\n\n\n\n\n\nLevantamento topográfico e perfil de frente de rua (Topomartins, desenho 3326TOP001, revisão A, julho de 2026);\n\n\n\nInformação prestada pelo promotor;\n\n\n\nConsulta ao portal LXi para tomar conhecimento das condicionantes urbanísticas do edifício;\n\n\n\nAnálise das condicionantes para estabelecer um cenário possível de intervenção e, com isso, a prestação de serviços necessária para o promotor.\n\nO lote, com uma área total de 384,30 m², tem frente para a Travessa do Oleiro, entre a Rua do Poço dos Negros e a Rua dos Poiais de São Bento, e é composto pelos seguintes elementos:\n\n\n\n\n\n\n\nElemento\n\n\n\nÁrea (m²)\n\n\n\n\n\nA – Edifício principal, 5 pisos\n\n\n\n150,60\n\n\n\n\n\nB – Anexo, 3 pisos\n\n\n\n19,10\n\n\n\n\n\nC – Anexo, 2 pisos\n\n\n\n38,00\n\n\n\n\n\nD – Anexo, 1 piso\n\n\n\n13,50\n\n\n\n\n\nL1 – Logradouro\n\n\n\n36,10\n\n\n\n\n\nL2 – Logradouro\n\n\n\n127,00\n\n\n\n\n\nLimite do lote – área total\n\n\n\n384,30\n\n\n\n\n\nE – Área bruta privativa subterrânea\n\n\n\n32,70\n\nCom base nestes elementos, estimamos uma área bruta de construção existente de cerca de 930 m² (edifício principal com cerca de 750 m² em 5 pisos, anexos e área subterrânea).\n\nO terreno apresenta um desnível acentuado: a Travessa do Oleiro sobe da cota 12,15 (Rua do Poço dos Negros) até à cota 21,04 (Rua dos Poiais de São Bento). A fachada do edifício principal assenta entre as cotas 15,36 e 16,18 e o logradouro posterior (L2) situa-se aproximadamente à cota 19,6, cerca de 4 m acima da entrada pela Travessa do Oleiro.\n\nDa análise do levantamento e das condicionantes do local, apresentamos uma proposta de prestação de serviços assente nas seguintes premissas:\n\n\n\n\n\nDemolição do interior do edifício existente e manutenção das fachadas principal e tardoz;\n\n\n\nReconversão do conjunto em apartamentos turísticos, a licenciar como empreendimento turístico nos termos do Regime Jurídico dos Empreendimentos Turísticos (Decreto-Lei n.º 39/2008, na sua redação atual);\n\n\n\nO número e a tipologia das unidades de alojamento serão definidos na fase de Programa Base, em função das condicionantes urbanísticas, dos requisitos de classificação e do programa do promotor;\n\n\n\nEstudo do aproveitamento dos anexos (B, C e D) e dos logradouros como áreas de apoio e espaços exteriores.\n\nNOTA: As áreas indicadas resultam do levantamento topográfico e servem de orientação para a elaboração da proposta de honorários. As áreas brutas de construção existentes serão confirmadas com o levantamento arquitetónico do edifício.\n\nPara além do projeto de Arquitetura e Plano de Acessibilidades, faz parte desta proposta:\n\n\n\n\n\nA coordenação dos diversos projetos de especialidades com o projeto de arquitetura;\n\n\n\nA representação do requerente no portal Loja Lisboa e as submissões dos projetos no portal;\n\n\n\nO acompanhamento do pedido de parecer ao Turismo de Portugal, I.P., quando aplicável ao licenciamento do empreendimento turístico.\n\n", "headingLevel": "h1", "pageBreakBefore": true}, "after": {"html": "<p>A nossa proposta refere-se à elaboração dos estudos e Projecto de Arquitectura e Assistência Técnica à execução da obra de alteração de um conjunto edificado, sito na Travessa do Oleiro, n.º 11 a 15, freguesia da Misericórdia, em Lisboa, para a instalação de apartamentos turísticos (serviced apartments).</p><p>A Pedra Silva Arquitectos (PSA) será a autora do projeto de arquitetura e a equipa projetista responsável pelo processo, trabalhando em parceria com o designer de interiores indicado pelo Cliente. A PSA irá integrar as soluções de interiores nos projetos de licenciamento e de execução e assegurar a coordenação geral das especialidades.</p><p>A proposta apresentada assenta na seguinte informação sobre o edifício existente:</p><ul><li><p>Levantamento topográfico e perfil de frente de rua (Topomartins, desenho 3326TOP001, revisão A, julho de 2026);</p></li><li><p>Informação prestada pelo promotor;</p></li><li><p>Conceito de design de interiores a fornecer pelo designer de interiores indicado pelo Cliente;</p></li><li><p>Consulta ao portal LXi para tomar conhecimento das condicionantes urbanísticas do edifício;</p></li><li><p>Análise das condicionantes para estabelecer um cenário possível de intervenção e, com isso, a prestação de serviços necessária para o promotor.</p></li></ul><p>O lote, com uma área total de 384,30 m², tem frente para a Travessa do Oleiro, entre a Rua do Poço dos Negros e a Rua dos Poiais de São Bento, e é composto pelos seguintes elementos:</p><table style=\"min-width: 50px;\"><colgroup><col style=\"min-width: 25px;\"><col style=\"min-width: 25px;\"></colgroup><tbody><tr><th colspan=\"1\" rowspan=\"1\"><p>Elemento</p></th><th colspan=\"1\" rowspan=\"1\"><p>Área (m²)</p></th></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>A – Edifício principal, 5 pisos</p></td><td colspan=\"1\" rowspan=\"1\"><p>150,60</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>B – Anexo, 3 pisos</p></td><td colspan=\"1\" rowspan=\"1\"><p>19,10</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>C – Anexo, 2 pisos</p></td><td colspan=\"1\" rowspan=\"1\"><p>38,00</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>D – Anexo, 1 piso</p></td><td colspan=\"1\" rowspan=\"1\"><p>13,50</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>L1 – Logradouro</p></td><td colspan=\"1\" rowspan=\"1\"><p>36,10</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>L2 – Logradouro</p></td><td colspan=\"1\" rowspan=\"1\"><p>127,00</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p><strong>Limite do lote – área total</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p><strong>384,30</strong></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>E – Área bruta privativa subterrânea</p></td><td colspan=\"1\" rowspan=\"1\"><p>32,70</p></td></tr></tbody></table><p>Com base nestes elementos, estimamos uma área bruta de construção existente de cerca de <strong>930 m²</strong> (edifício principal com cerca de 750 m² em 5 pisos, anexos e área subterrânea).</p><p>O terreno apresenta um desnível acentuado: a Travessa do Oleiro sobe da cota 12,15 (Rua do Poço dos Negros) até à cota 21,04 (Rua dos Poiais de São Bento). A fachada do edifício principal assenta entre as cotas 15,36 e 16,18 e o logradouro posterior (L2) situa-se aproximadamente à cota 19,6, cerca de 4 m acima da entrada pela Travessa do Oleiro.</p><p>Da análise do levantamento e das condicionantes do local, apresentamos uma proposta de prestação de serviços assente nas seguintes premissas:</p><ul><li><p>Demolição do interior do edifício existente e manutenção das fachadas principal e tardoz;</p></li><li><p>Reconversão do conjunto em apartamentos turísticos, a licenciar como empreendimento turístico nos termos do Regime Jurídico dos Empreendimentos Turísticos (Decreto-Lei n.º 39/2008, na sua redação atual);</p></li><li><p>O número e a tipologia das unidades de alojamento serão definidos na fase de Programa Base, em função das condicionantes urbanísticas, dos requisitos de classificação e do programa do promotor, em articulação com o designer de interiores indicado pelo Cliente;</p></li><li><p>Estudo do aproveitamento dos anexos (B, C e D) e dos logradouros como áreas de apoio e espaços exteriores.</p></li></ul><p><strong>NOTA:</strong> As áreas indicadas resultam do levantamento topográfico e servem de orientação para a elaboração da proposta de honorários. As áreas brutas de construção existentes serão confirmadas com o levantamento arquitetónico do edifício.</p><p>Para além do projeto de Arquitetura e Plano de Acessibilidades, faz parte desta proposta:</p><ul><li><p>A coordenação dos diversos projetos de especialidades com o projeto de arquitetura;</p></li><li><p>A representação do requerente no portal Loja Lisboa e as submissões dos projetos no portal;</p></li><li><p>O acompanhamento do pedido de parecer ao Turismo de Portugal, I.P., quando aplicável ao licenciamento do empreendimento turístico.</p></li></ul><p></p><p>Em cada fase, a PSA só poderá desenvolver o seu trabalho após a receção dos elementos necessários por parte do Cliente e do designer de interiores. Caso estes elementos não sejam recebidos nos prazos acordados, a PSA não poderá ser responsabilizada por atrasos ou incumprimento de prazos.</p><p>Repartição de responsabilidades: a PSA é responsável pelo projeto de arquitetura do edifício, incluindo as áreas técnicas e de apoio, a integração das soluções de interiores nos projetos de licenciamento e de execução e a coordenação geral das especialidades; o designer de interiores indicado pelo Cliente é responsável pelo conceito e projeto de design de interiores dos apartamentos turísticos e das áreas comuns, incluindo mobiliário, equipamento e decoração (FF&amp;E) e iluminação decorativa. A fronteira detalhada entre os dois âmbitos será confirmada na fase de Programa.</p>", "text": "A nossa proposta refere-se à elaboração dos estudos e Projecto de Arquitectura e Assistência Técnica à execução da obra de alteração de um conjunto edificado, sito na Travessa do Oleiro, n.º 11 a 15, freguesia da Misericórdia, em Lisboa, para a instalação de apartamentos turísticos (serviced apartments).\nA Pedra Silva Arquitectos (PSA) será a autora do projeto de arquitetura e a equipa projetista responsável pelo processo, trabalhando em parceria com o designer de interiores indicado pelo Cliente. A PSA irá integrar as soluções de interiores nos projetos de licenciamento e de execução e assegurar a coordenação geral das especialidades.\nA proposta apresentada assenta na seguinte informação sobre o edifício existente:\nLevantamento topográfico e perfil de frente de rua (Topomartins, desenho 3326TOP001, revisão A, julho de 2026);\nInformação prestada pelo promotor;\nConceito de design de interiores a fornecer pelo designer de interiores indicado pelo Cliente;\nConsulta ao portal LXi para tomar conhecimento das condicionantes urbanísticas do edifício;\nAnálise das condicionantes para estabelecer um cenário possível de intervenção e, com isso, a prestação de serviços necessária para o promotor.\nO lote, com uma área total de 384,30 m², tem frente para a Travessa do Oleiro, entre a Rua do Poço dos Negros e a Rua dos Poiais de São Bento, e é composto pelos seguintes elementos:\nElemento\nÁrea (m²)\nA – Edifício principal, 5 pisos\n150,60\nB – Anexo, 3 pisos\n19,10\nC – Anexo, 2 pisos\n38,00\nD – Anexo, 1 piso\n13,50\nL1 – Logradouro\n36,10\nL2 – Logradouro\n127,00\nLimite do lote – área total\n384,30\nE – Área bruta privativa subterrânea\n32,70\nCom base nestes elementos, estimamos uma área bruta de construção existente de cerca de\n930 m²\n(edifício principal com cerca de 750 m² em 5 pisos, anexos e área subterrânea).\nO terreno apresenta um desnível acentuado: a Travessa do Oleiro sobe da cota 12,15 (Rua do Poço dos Negros) até à cota 21,04 (Rua dos Poiais de São Bento). A fachada do edifício principal assenta entre as cotas 15,36 e 16,18 e o logradouro posterior (L2) situa-se aproximadamente à cota 19,6, cerca de 4 m acima da entrada pela Travessa do Oleiro.\nDa análise do levantamento e das condicionantes do local, apresentamos uma proposta de prestação de serviços assente nas seguintes premissas:\nDemolição do interior do edifício existente e manutenção das fachadas principal e tardoz;\nReconversão do conjunto em apartamentos turísticos, a licenciar como empreendimento turístico nos termos do Regime Jurídico dos Empreendimentos Turísticos (Decreto-Lei n.º 39/2008, na sua redação atual);\nO número e a tipologia das unidades de alojamento serão definidos na fase de Programa Base, em função das condicionantes urbanísticas, dos requisitos de classificação e do programa do promotor, em articulação com o designer de interiores indicado pelo Cliente;\nEstudo do aproveitamento dos anexos (B, C e D) e dos logradouros como áreas de apoio e espaços exteriores.\nNOTA:\nAs áreas indicadas resultam do levantamento topográfico e servem de orientação para a elaboração da proposta de honorários. As áreas brutas de construção existentes serão confirmadas com o levantamento arquitetónico do edifício.\nPara além do projeto de Arquitetura e Plano de Acessibilidades, faz parte desta proposta:\nA coordenação dos diversos projetos de especialidades com o projeto de arquitetura;\nA representação do requerente no portal Loja Lisboa e as submissões dos projetos no portal;\nO acompanhamento do pedido de parecer ao Turismo de Portugal, I.P., quando aplicável ao licenciamento do empreendimento turístico.\nEm cada fase, a PSA só poderá desenvolver o seu trabalho após a receção dos elementos necessários por parte do Cliente e do designer de interiores. Caso estes elementos não sejam recebidos nos prazos acordados, a PSA não poderá ser responsabilizada por atrasos ou incumprimento de prazos.\nRepartição de responsabilidades: a PSA é responsável pelo projeto de arquitetura do edifício, incluindo as áreas técnicas e de apoio, a integração das soluções de interiores nos projetos de licenciamento e de execução e a coordenação geral das especialidades; o designer de interiores indicado pelo Cliente é responsável pelo conceito e projeto de design de interiores dos apartamentos turísticos e das áreas comuns, incluindo mobiliário, equipamento e decoração (FF&E) e iluminação decorativa. A fronteira detalhada entre os dois âmbitos será confirmada na fase de Programa.", "headingLevel": "h1", "pageBreakBefore": true}}, {"id": "216a1529-c8e2-42cd-acb0-5398f9a84b84", "title": "Programa", "sort_order": 90, "before": {"html": "<p></p>", "text": "", "client_info": "Levantamento arquitetónico do edifício (plantas, cortes e alçados), por técnico credenciado\nLevantamento dos alçados da frente de rua do quarteirão\nPrograma e objetivos do promotor, incluindo o modelo de exploração pretendido\nLimites orçamentais da obra\nDocumentação do imóvel (caderneta predial e certidão do registo predial)", "deliverables": "Programa Base do empreendimento (unidades de alojamento e áreas de apoio).\nSíntese das condicionantes urbanísticas e regulamentares.\nEstratégia de intervenção.", "headingLevel": "h2", "objective_html": "<p>Nest fase iremos reunir toda a informação do Cliente que possibilite compreender as suas intenções para o Projeto e toda a informação relevante para o seu desenvolvimento, tal como limitações ou restrições aplicáveis, entre elas as condicionantes urbanísticas, os requisitos de classificação do empreendimento turístico e os limites orçamentais.</p><p>Consiste em criar e desenvolver uma estratégia de intervenção e propor uma determinada abordagem arquitetónica, incluindo a definição preliminar do número e da tipologia das unidades de alojamento, de modo a cumprir com os seus objetivos.</p>", "objective_text": "Nest fase iremos reunir toda a informação do Cliente que possibilite compreender as suas intenções para o Projeto e toda a informação relevante para o seu desenvolvimento, tal como limitações ou restrições aplicáveis, entre elas as condicionantes urbanísticas, os requisitos de classificação do empreendimento turístico e os limites orçamentais.\n\nConsiste em criar e desenvolver uma estratégia de intervenção e propor uma determinada abordagem arquitetónica, incluindo a definição preliminar do número e da tipologia das unidades de alojamento, de modo a cumprir com os seus objetivos.", "key_activities_html": "<ul><li><p>Visita ao local / reunião com o cliente;</p></li><li><p>Consulta de elementos sobre o edifício (no arquivo municipal ou outros);</p></li><li><p>Consulta da legislação aplicável à intervenção, incluindo o regime jurídico dos empreendimentos turísticos e os respetivos requisitos de classificação;</p></li><li><p>Definição preliminar do programa: número, tipologia e áreas das unidades de alojamento e das áreas de apoio;</p></li><li><p>Eventual agendamento de reunião com a Câmara Municipal de Lisboa para esclarecimentos.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nVisita ao local / reunião com o cliente;\n\n\n\nConsulta de elementos sobre o edifício (no arquivo municipal ou outros);\n\n\n\nConsulta da legislação aplicável à intervenção, incluindo o regime jurídico dos empreendimentos turísticos e os respetivos requisitos de classificação;\n\n\n\nDefinição preliminar do programa: número, tipologia e áreas das unidades de alojamento e das áreas de apoio;\n\n\n\nEventual agendamento de reunião com a Câmara Municipal de Lisboa para esclarecimentos.\n\n", "stage_approval_html": "<p>No final desta fase, o cliente aprova o Programa Base, que servirá de referência para o desenvolvimento do Estudo Prévio.</p>", "stage_approval_text": "No final desta fase, o cliente aprova o Programa Base, que servirá de referência para o desenvolvimento do Estudo Prévio."}, "after": {"html": "<p></p>", "text": "", "client_info": "Levantamento arquitetónico do edifício (plantas, cortes e alçados), por técnico credenciado\nLevantamento dos alçados da frente de rua do quarteirão\nPrograma e objetivos do promotor, incluindo o modelo de exploração pretendido\nLimites orçamentais da obra\nDocumentação do imóvel (caderneta predial e certidão do registo predial)\nConceito e elementos de design de interiores a fornecer pelo designer de interiores indicado pelo Cliente, nos prazos acordados", "deliverables": "Programa Base do empreendimento (unidades de alojamento e áreas de apoio).\nSíntese das condicionantes urbanísticas e regulamentares.\nEstratégia de intervenção.", "headingLevel": "h2", "objective_html": "<p>O Programa faz parte desta prestação de serviços e é desenvolvido pela PSA em conjunto com o Cliente e o designer de interiores por ele indicado.</p><p>Nest fase iremos reunir toda a informação do Cliente que possibilite compreender as suas intenções para o Projeto e toda a informação relevante para o seu desenvolvimento, tal como limitações ou restrições aplicáveis, entre elas as condicionantes urbanísticas, os requisitos de classificação do empreendimento turístico e os limites orçamentais.</p><p>Consiste em criar e desenvolver uma estratégia de intervenção e propor uma determinada abordagem arquitetónica, incluindo a definição preliminar do número e da tipologia das unidades de alojamento, de modo a cumprir com os seus objetivos.</p>", "objective_text": "O Programa faz parte desta prestação de serviços e é desenvolvido pela PSA em conjunto com o Cliente e o designer de interiores por ele indicado.\nNest fase iremos reunir toda a informação do Cliente que possibilite compreender as suas intenções para o Projeto e toda a informação relevante para o seu desenvolvimento, tal como limitações ou restrições aplicáveis, entre elas as condicionantes urbanísticas, os requisitos de classificação do empreendimento turístico e os limites orçamentais.\nConsiste em criar e desenvolver uma estratégia de intervenção e propor uma determinada abordagem arquitetónica, incluindo a definição preliminar do número e da tipologia das unidades de alojamento, de modo a cumprir com os seus objetivos.", "key_activities_html": "<ul><li><p>Visita ao local / reunião com o Cliente e o designer de interiores indicado pelo Cliente;</p></li><li><p>Consulta de elementos sobre o edifício (no arquivo municipal ou outros);</p></li><li><p>Consulta da legislação aplicável à intervenção, incluindo o regime jurídico dos empreendimentos turísticos e os respetivos requisitos de classificação;</p></li><li><p>Definição preliminar do programa: número, tipologia e áreas das unidades de alojamento e das áreas de apoio;</p></li><li><p>Eventual agendamento de reunião com a Câmara Municipal de Lisboa para esclarecimentos.</p></li></ul><p></p>", "key_activities_text": "Visita ao local / reunião com o Cliente e o designer de interiores indicado pelo Cliente;\nConsulta de elementos sobre o edifício (no arquivo municipal ou outros);\nConsulta da legislação aplicável à intervenção, incluindo o regime jurídico dos empreendimentos turísticos e os respetivos requisitos de classificação;\nDefinição preliminar do programa: número, tipologia e áreas das unidades de alojamento e das áreas de apoio;\nEventual agendamento de reunião com a Câmara Municipal de Lisboa para esclarecimentos.", "stage_approval_html": "<p>No final desta fase, o cliente aprova o Programa Base, que servirá de referência para o desenvolvimento do Estudo Prévio.</p>", "stage_approval_text": "No final desta fase, o cliente aprova o Programa Base, que servirá de referência para o desenvolvimento do Estudo Prévio."}}, {"id": "d6c5bb08-ce52-4e08-815f-46ea4c6bf4db", "title": "Estudo Prévio", "sort_order": 100, "before": {"html": "<p></p>", "text": "", "client_info": "Topographic survey of the plot\nBudget indications, if available at this stage\nAny existing drawings and documentation provided by the Client\nObjectives and key features of the project\n", "deliverables": "Plantas, cortes e alçados do estudo prévio.\nQuadro de áreas e de unidades de alojamento.\nMemória descritiva sumária.\n6 imagens 3D (CGI) ilustrativas do conceito de arquitetura.", "headingLevel": "h2", "objective_html": "<p>Depois de definido e aprovado o Programa Base, vamos desenvolver os conceitos que foram definidos e apresentar soluções através de desenhos ou outros elementos que facilitem a sua compreensão do projeto, como a sua organização e a sua aparência final.</p><p>Iremos definir a globalidade da intervenção, de acordo com as suas pretensões para a otimização do edifício, dentro do contexto da legislação em vigor para o local, e estudar a melhor estratégia de encaminhar o processo para a obtenção da aprovação do licenciamento camarário.</p><p>É ainda nosso papel integrar o trabalho do Interior Design&nbsp; e  os projetistas das especialidades para, em conjunto com estes, estudar as soluções do ponto de vista técnico, construtivo e de custos.</p>", "objective_text": "Depois de definido e aprovado o Programa Base, vamos desenvolver os conceitos que foram definidos e apresentar soluções através de desenhos ou outros elementos que facilitem a sua compreensão do projeto, como a sua organização e a sua aparência final.\n\nIremos definir a globalidade da intervenção, de acordo com as suas pretensões para a otimização do edifício, dentro do contexto da legislação em vigor para o local, e estudar a melhor estratégia de encaminhar o processo para a obtenção da aprovação do licenciamento camarário.\n\nÉ ainda nosso papel integrar o trabalho do Interior Design  e  os projetistas das especialidades para, em conjunto com estes, estudar as soluções do ponto de vista técnico, construtivo e de custos.", "resources_visible": true, "client_info_visible": false, "key_activities_html": "<ul><li><p>Estudos do layout definitivo dos vários pisos e das unidades de alojamento;</p></li><li><p>Estudos de cortes e alçados;</p></li><li><p>Estudos de volumetria;</p></li><li><p>Estudos de materiais exteriores a usar;</p></li><li><p>Cálculo de áreas, cérceas e índices a cumprir;</p></li><li><p>Verificação preliminar dos requisitos de classificação aplicáveis aos apartamentos turísticos.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nEstudos do layout definitivo dos vários pisos e das unidades de alojamento;\n\n\n\nEstudos de cortes e alçados;\n\n\n\nEstudos de volumetria;\n\n\n\nEstudos de materiais exteriores a usar;\n\n\n\nCálculo de áreas, cérceas e índices a cumprir;\n\n\n\nVerificação preliminar dos requisitos de classificação aplicáveis aos apartamentos turísticos.\n\n", "stage_approval_html": "<p>Prevemos ir ao encontro dos seus objetivos através da apresentação de uma proposta de estudo prévio, desenvolvida durante o tempo estimado e com os recursos previstos no planeamento apresentado.</p><p>A nossa equipa fará as necessárias afinações na proposta de estudo prévio de forma a obter a sua total satisfação, desde que estas estejam dentro do número de horas previsto na nossa proposta de honorários.</p>", "stage_approval_text": "Prevemos ir ao encontro dos seus objetivos através da apresentação de uma proposta de estudo prévio, desenvolvida durante o tempo estimado e com os recursos previstos no planeamento apresentado.\n\nA nossa equipa fará as necessárias afinações na proposta de estudo prévio de forma a obter a sua total satisfação, desde que estas estejam dentro do número de horas previsto na nossa proposta de honorários."}, "after": {"html": "<p></p>", "text": "", "client_info": "Topographic survey of the plot\nBudget indications, if available at this stage\nAny existing drawings and documentation provided by the Client\nObjectives and key features of the project\n", "deliverables": "Plantas, cortes e alçados do estudo prévio.\nQuadro de áreas e de unidades de alojamento.\nMemória descritiva sumária.\n6 imagens 3D (CGI) ilustrativas do conceito de arquitetura.", "headingLevel": "h2", "objective_html": "<p>Depois de definido e aprovado o Programa Base, vamos desenvolver, em articulação com o designer de interiores indicado pelo Cliente, os conceitos que foram definidos e apresentar soluções através de desenhos ou outros elementos que facilitem a sua compreensão do projeto, como a sua organização e a sua aparência final.</p><p>Iremos definir a globalidade da intervenção, de acordo com as suas pretensões para a otimização do edifício, dentro do contexto da legislação em vigor para o local, e estudar a melhor estratégia de encaminhar o processo para a obtenção da aprovação do licenciamento camarário.</p><p>É ainda nosso papel integrar as soluções do designer de interiores indicado pelo Cliente no projeto de arquitetura e articular o trabalho dos projetistas das especialidades para, em conjunto com estes, estudar as soluções do ponto de vista técnico, construtivo e de custos.</p>", "objective_text": "Depois de definido e aprovado o Programa Base, vamos desenvolver, em articulação com o designer de interiores indicado pelo Cliente, os conceitos que foram definidos e apresentar soluções através de desenhos ou outros elementos que facilitem a sua compreensão do projeto, como a sua organização e a sua aparência final.\nIremos definir a globalidade da intervenção, de acordo com as suas pretensões para a otimização do edifício, dentro do contexto da legislação em vigor para o local, e estudar a melhor estratégia de encaminhar o processo para a obtenção da aprovação do licenciamento camarário.\nÉ ainda nosso papel integrar as soluções do designer de interiores indicado pelo Cliente no projeto de arquitetura e articular o trabalho dos projetistas das especialidades para, em conjunto com estes, estudar as soluções do ponto de vista técnico, construtivo e de custos.", "resources_visible": true, "client_info_visible": false, "key_activities_html": "<ul><li><p>Reunião inicial com o Cliente e o designer de interiores indicado pelo Cliente para confirmar o Programa e os objetivos do projeto;</p></li><li><p>Apresentação de toda a equipa do projeto, das especialidades ao design de interiores;</p></li><li><p>Estudos do layout definitivo dos vários pisos e das unidades de alojamento;</p></li><li><p>Estudos de cortes e alçados;</p></li><li><p>Estudos de volumetria;</p></li><li><p>Estudos de materiais exteriores a usar;</p></li><li><p>Cálculo de áreas, cérceas e índices a cumprir;</p></li><li><p>Verificação preliminar dos requisitos de classificação aplicáveis aos apartamentos turísticos.</p></li></ul><p></p>", "key_activities_text": "Reunião inicial com o Cliente e o designer de interiores indicado pelo Cliente para confirmar o Programa e os objetivos do projeto;\nApresentação de toda a equipa do projeto, das especialidades ao design de interiores;\nEstudos do layout definitivo dos vários pisos e das unidades de alojamento;\nEstudos de cortes e alçados;\nEstudos de volumetria;\nEstudos de materiais exteriores a usar;\nCálculo de áreas, cérceas e índices a cumprir;\nVerificação preliminar dos requisitos de classificação aplicáveis aos apartamentos turísticos.", "stage_approval_html": "<p>Prevemos ir ao encontro dos seus objetivos através da apresentação de uma proposta de estudo prévio, desenvolvida durante o tempo estimado e com os recursos previstos no planeamento apresentado.</p><p>A nossa equipa fará as necessárias afinações na proposta de estudo prévio de forma a obter a sua total satisfação, desde que estas estejam dentro do número de horas previsto na nossa proposta de honorários.</p>", "stage_approval_text": "Prevemos ir ao encontro dos seus objetivos através da apresentação de uma proposta de estudo prévio, desenvolvida durante o tempo estimado e com os recursos previstos no planeamento apresentado.\n\nA nossa equipa fará as necessárias afinações na proposta de estudo prévio de forma a obter a sua total satisfação, desde que estas estejam dentro do número de horas previsto na nossa proposta de honorários."}}, {"id": "201f0fcb-14e9-4488-b1de-76cbf1101ef3", "title": "Licenciamento", "sort_order": 120, "before": {"html": "<p></p>", "text": "", "client_info": "Aprovação do PIP pela Câmara Municipal de Lisboa\nProjetos de especialidades, a contratar pelo promotor\nEstudo geotécnico, se necessário", "deliverables": "Projeto de Arquitetura e Plano de Acessibilidades (peças escritas e desenhadas).\nProcesso de licenciamento submetido no portal Loja Lisboa.\nCoordenação dos projetos de especialidades para licenciamento.", "headingLevel": "h2", "objective_html": "<p>A fase de projeto de licenciamento consiste no desenvolvimento da proposta do PIP aprovado, através da interação com os projetistas de especialidades e da elaboração dos elementos solicitados pela Câmara Municipal para a instrução e submissão do processo, de acordo com a legislação aplicável, incluindo os requisitos aplicáveis aos empreendimentos turísticos.</p><p>Serão definidas nesta fase as soluções construtivas e será elaborado um estudo preliminar da integração das infraestruturas (gás, águas, esgotos, ventilação, eletricidade, telecomunicações) e, em especial, das estruturas e das condicionantes térmicas e acústicas na construção.</p><p>Definidas as soluções em conjunto com os projetistas de especialidades, serão feitos os necessários ajustes nos desenhos de arquitetura e preparados todos os elementos necessários (peças escritas, peças desenhadas e documentos) à submissão do processo de licenciamento no portal da Câmara Municipal de Lisboa.</p>", "objective_text": "A fase de projeto de licenciamento consiste no desenvolvimento da proposta do PIP aprovado, através da interação com os projetistas de especialidades e da elaboração dos elementos solicitados pela Câmara Municipal para a instrução e submissão do processo, de acordo com a legislação aplicável, incluindo os requisitos aplicáveis aos empreendimentos turísticos.\n\nSerão definidas nesta fase as soluções construtivas e será elaborado um estudo preliminar da integração das infraestruturas (gás, águas, esgotos, ventilação, eletricidade, telecomunicações) e, em especial, das estruturas e das condicionantes térmicas e acústicas na construção.\n\nDefinidas as soluções em conjunto com os projetistas de especialidades, serão feitos os necessários ajustes nos desenhos de arquitetura e preparados todos os elementos necessários (peças escritas, peças desenhadas e documentos) à submissão do processo de licenciamento no portal da Câmara Municipal de Lisboa.", "client_info_visible": true, "key_activities_html": "<ul><li><p>Definição de soluções construtivas e articulação das exigências das especialidades;</p></li><li><p>Verificação e coordenação dos elementos dos projetos de especialidades;</p></li><li><p>Projeto de Arquitetura e Plano de Acessibilidades – peças desenhadas e peças escritas em formato digital, a entregar na Câmara Municipal de Lisboa;</p></li><li><p>Submissão dos projetos na Câmara Municipal;</p></li><li><p>Acompanhamento do pedido de parecer ao Turismo de Portugal, I.P., quando aplicável;</p></li><li><p>Seguimento do processo na Câmara Municipal de Lisboa e resposta a eventuais notificações, desde que estas tenham sido motivadas por lapsos da equipa de projeto e não por opções de projeto impostas pelo dono de obra.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nDefinição de soluções construtivas e articulação das exigências das especialidades;\n\n\n\nVerificação e coordenação dos elementos dos projetos de especialidades;\n\n\n\nProjeto de Arquitetura e Plano de Acessibilidades – peças desenhadas e peças escritas em formato digital, a entregar na Câmara Municipal de Lisboa;\n\n\n\nSubmissão dos projetos na Câmara Municipal;\n\n\n\nAcompanhamento do pedido de parecer ao Turismo de Portugal, I.P., quando aplicável;\n\n\n\nSeguimento do processo na Câmara Municipal de Lisboa e resposta a eventuais notificações, desde que estas tenham sido motivadas por lapsos da equipa de projeto e não por opções de projeto impostas pelo dono de obra.\n\n", "stage_approval_html": "<p>A nossa proposta para a fase de licenciamento é apresentada considerando que a proposta de PIP é aprovada. Caso o licenciamento tenha de ser diferente da proposta apresentada como PIP e tenham de ser elaborados novos estudos, a nossa proposta de honorários e o calendário previsto terão de ser revistos.</p><p>Os serviços prestados pelos projetistas de especialidades não fazem parte desta proposta de honorários. Os projetos de especialidades são feitos por equipas externas à Pedra Silva Arquitectos e cada equipa apresenta o seu preço separadamente.</p>", "stage_approval_text": "A nossa proposta para a fase de licenciamento é apresentada considerando que a proposta de PIP é aprovada. Caso o licenciamento tenha de ser diferente da proposta apresentada como PIP e tenham de ser elaborados novos estudos, a nossa proposta de honorários e o calendário previsto terão de ser revistos.\n\nOs serviços prestados pelos projetistas de especialidades não fazem parte desta proposta de honorários. Os projetos de especialidades são feitos por equipas externas à Pedra Silva Arquitectos e cada equipa apresenta o seu preço separadamente."}, "after": {"html": "<p></p>", "text": "", "client_info": "Aprovação do PIP pela Câmara Municipal de Lisboa\nProjetos de especialidades, a contratar pelo promotor\nEstudo geotécnico, se necessário\nElementos do designer de interiores indicado pelo Cliente necessários à integração das soluções de interiores no licenciamento", "deliverables": "Projeto de Arquitetura e Plano de Acessibilidades (peças escritas e desenhadas).\nProcesso de licenciamento submetido no portal Loja Lisboa.\nCoordenação dos projetos de especialidades para licenciamento.", "headingLevel": "h2", "objective_html": "<p>A fase de projeto de licenciamento consiste no desenvolvimento da proposta do PIP aprovado, através da interação com o designer de interiores indicado pelo Cliente e com os projetistas de especialidades e da elaboração dos elementos solicitados pela Câmara Municipal para a instrução e submissão do processo, de acordo com a legislação aplicável, incluindo os requisitos aplicáveis aos empreendimentos turísticos.</p><p>Serão definidas nesta fase as soluções construtivas e será elaborado um estudo preliminar da integração das infraestruturas (gás, águas, esgotos, ventilação, eletricidade, telecomunicações) e, em especial, das estruturas e das condicionantes térmicas e acústicas na construção.</p><p>Definidas as soluções em conjunto com os projetistas de especialidades, serão feitos os necessários ajustes nos desenhos de arquitetura e preparados todos os elementos necessários (peças escritas, peças desenhadas e documentos) à submissão do processo de licenciamento no portal da Câmara Municipal de Lisboa.</p>", "objective_text": "A fase de projeto de licenciamento consiste no desenvolvimento da proposta do PIP aprovado, através da interação com o designer de interiores indicado pelo Cliente e com os projetistas de especialidades e da elaboração dos elementos solicitados pela Câmara Municipal para a instrução e submissão do processo, de acordo com a legislação aplicável, incluindo os requisitos aplicáveis aos empreendimentos turísticos.\nSerão definidas nesta fase as soluções construtivas e será elaborado um estudo preliminar da integração das infraestruturas (gás, águas, esgotos, ventilação, eletricidade, telecomunicações) e, em especial, das estruturas e das condicionantes térmicas e acústicas na construção.\nDefinidas as soluções em conjunto com os projetistas de especialidades, serão feitos os necessários ajustes nos desenhos de arquitetura e preparados todos os elementos necessários (peças escritas, peças desenhadas e documentos) à submissão do processo de licenciamento no portal da Câmara Municipal de Lisboa.", "client_info_visible": true, "key_activities_html": "<ul><li><p>Definição de soluções construtivas e articulação das exigências das especialidades;</p></li><li><p>Verificação e coordenação dos elementos dos projetos de especialidades;</p></li><li><p>Projeto de Arquitetura e Plano de Acessibilidades – peças desenhadas e peças escritas em formato digital, a entregar na Câmara Municipal de Lisboa;</p></li><li><p>Submissão dos projetos na Câmara Municipal;</p></li><li><p>Acompanhamento do pedido de parecer ao Turismo de Portugal, I.P., quando aplicável;</p></li><li><p>Seguimento do processo na Câmara Municipal de Lisboa e resposta a eventuais notificações, desde que estas tenham sido motivadas por lapsos da equipa de projeto e não por opções de projeto impostas pelo dono de obra.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nDefinição de soluções construtivas e articulação das exigências das especialidades;\n\n\n\nVerificação e coordenação dos elementos dos projetos de especialidades;\n\n\n\nProjeto de Arquitetura e Plano de Acessibilidades – peças desenhadas e peças escritas em formato digital, a entregar na Câmara Municipal de Lisboa;\n\n\n\nSubmissão dos projetos na Câmara Municipal;\n\n\n\nAcompanhamento do pedido de parecer ao Turismo de Portugal, I.P., quando aplicável;\n\n\n\nSeguimento do processo na Câmara Municipal de Lisboa e resposta a eventuais notificações, desde que estas tenham sido motivadas por lapsos da equipa de projeto e não por opções de projeto impostas pelo dono de obra.\n\n", "stage_approval_html": "<p>A nossa proposta para a fase de licenciamento é apresentada considerando que a proposta de PIP é aprovada. Caso o licenciamento tenha de ser diferente da proposta apresentada como PIP e tenham de ser elaborados novos estudos, a nossa proposta de honorários e o calendário previsto terão de ser revistos.</p><p>Os serviços prestados pelos projetistas de especialidades não fazem parte desta proposta de honorários. Os projetos de especialidades são feitos por equipas externas à Pedra Silva Arquitectos e cada equipa apresenta o seu preço separadamente.</p>", "stage_approval_text": "A nossa proposta para a fase de licenciamento é apresentada considerando que a proposta de PIP é aprovada. Caso o licenciamento tenha de ser diferente da proposta apresentada como PIP e tenham de ser elaborados novos estudos, a nossa proposta de honorários e o calendário previsto terão de ser revistos.\n\nOs serviços prestados pelos projetistas de especialidades não fazem parte desta proposta de honorários. Os projetos de especialidades são feitos por equipas externas à Pedra Silva Arquitectos e cada equipa apresenta o seu preço separadamente."}}, {"id": "1224bb85-cfe5-4a12-81cc-ed0279ba25cf", "title": "Projecto de Execução", "sort_order": 130, "before": {"html": "<p></p>", "text": "", "client_info": "Aprovação do Projeto de Licenciamento\nLimites do custo da obra\nDefinição dos equipamentos e do nível de acabamentos pretendidos para as unidades de alojamento", "deliverables": "Peças desenhadas do projeto de execução (escalas 1:50 e 1:20).\nDescrição de acabamentos e equipamentos.\nMapa de Quantidades e Medições.\nEstimativa Orçamental.\nCaderno de Encargos e Condições Técnicas Especiais.", "headingLevel": "h2", "objective_html": "<p>Esta fase consiste no desenvolvimento do projeto de arquitetura, em que iremos desenvolver soluções estéticas e construtivas de acordo com as suas intenções e com as condicionantes do Projeto, ditadas pela legislação em vigor, pelos condicionalismos técnicos e pelos limites do custo da obra.</p><p>Iremos elaborar desenhos e elementos escritos que irão especificar todos os materiais e trabalhos necessários para a execução da obra. Está previsto que haja repetição das soluções, acabamentos e equipamentos a definir para as unidades de alojamento.</p><p>A partir desses elementos é elaborado um Mapa de Quantidades e Medições, que lhe servirá de base para efetuar os pedidos de orçamento aos construtores, e uma Estimativa Orçamental, que irá usar como referência quando receber os orçamentos dos construtores. Faremos também a coordenação do projeto de Arquitetura com os diferentes projetos de especialidades.</p>", "objective_text": "Esta fase consiste no desenvolvimento do projeto de arquitetura, em que iremos desenvolver soluções estéticas e construtivas de acordo com as suas intenções e com as condicionantes do Projeto, ditadas pela legislação em vigor, pelos condicionalismos técnicos e pelos limites do custo da obra.\n\nIremos elaborar desenhos e elementos escritos que irão especificar todos os materiais e trabalhos necessários para a execução da obra. Está previsto que haja repetição das soluções, acabamentos e equipamentos a definir para as unidades de alojamento.\n\nA partir desses elementos é elaborado um Mapa de Quantidades e Medições, que lhe servirá de base para efetuar os pedidos de orçamento aos construtores, e uma Estimativa Orçamental, que irá usar como referência quando receber os orçamentos dos construtores. Faremos também a coordenação do projeto de Arquitetura com os diferentes projetos de especialidades.", "key_activities_html": "<ul><li><p>Plantas gerais – escala 1:50;</p></li><li><p>Plantas de pavimentos e acabamentos – escala 1:50;</p></li><li><p>Plantas de tetos, indicando materiais e pontos de iluminação – escala 1:50;</p></li><li><p>Cortes e alçados – escala 1:50;</p></li><li><p>Detalhes de zonas específicas, tais como instalações sanitárias, kitchenettes e outras áreas conforme necessário – escala 1:20;</p></li><li><p>Mapas de vãos e de mobiliário fixo – escala apropriada;</p></li><li><p>Conjunto de detalhes construtivos – escala apropriada;</p></li><li><p>Coordenação com os projetos de especialidades.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nPlantas gerais – escala 1:50;\n\n\n\nPlantas de pavimentos e acabamentos – escala 1:50;\n\n\n\nPlantas de tetos, indicando materiais e pontos de iluminação – escala 1:50;\n\n\n\nCortes e alçados – escala 1:50;\n\n\n\nDetalhes de zonas específicas, tais como instalações sanitárias, kitchenettes e outras áreas conforme necessário – escala 1:20;\n\n\n\nMapas de vãos e de mobiliário fixo – escala apropriada;\n\n\n\nConjunto de detalhes construtivos – escala apropriada;\n\n\n\nCoordenação com os projetos de especialidades.\n\n", "stage_approval_html": "<p><strong>NOTA:</strong> É importante facultar-nos informação quanto aos limites do custo da obra, de forma a tomar decisões de acordo com as condicionantes.</p>", "stage_approval_text": "NOTA: É importante facultar-nos informação quanto aos limites do custo da obra, de forma a tomar decisões de acordo com as condicionantes."}, "after": {"html": "<p></p>", "text": "", "client_info": "Aprovação do Projeto de Licenciamento\nLimites do custo da obra\nDefinição dos equipamentos e do nível de acabamentos pretendidos para as unidades de alojamento\nProjeto e especificações de interiores, incluindo acabamentos, equipamento e iluminação decorativa, a fornecer pelo designer de interiores indicado pelo Cliente", "deliverables": "Peças desenhadas do projeto de execução (escalas 1:50 e 1:20).\nDescrição de acabamentos e equipamentos.\nMapa de Quantidades e Medições.\nEstimativa Orçamental.\nCaderno de Encargos e Condições Técnicas Especiais.", "headingLevel": "h2", "objective_html": "<p>Esta fase consiste no desenvolvimento do projeto de arquitetura, em que iremos desenvolver soluções estéticas e construtivas de acordo com as intenções do promotor, as soluções do designer de interiores indicado pelo Cliente e as condicionantes do Projeto, ditadas pela legislação em vigor, pelos condicionalismos técnicos e pelos limites do custo da obra.</p><p>Iremos elaborar desenhos e elementos escritos que irão especificar todos os materiais e trabalhos necessários para a execução da obra. Está previsto que haja repetição das soluções, acabamentos e equipamentos a definir para as unidades de alojamento.</p><p>A partir desses elementos é elaborado um Mapa de Quantidades e Medições, que lhe servirá de base para efetuar os pedidos de orçamento aos construtores, e uma Estimativa Orçamental, que irá usar como referência quando receber os orçamentos dos construtores. Faremos também a integração das soluções do designer de interiores indicado pelo Cliente no projeto de Arquitetura e a coordenação com os diferentes projetos de especialidades.</p>", "objective_text": "Esta fase consiste no desenvolvimento do projeto de arquitetura, em que iremos desenvolver soluções estéticas e construtivas de acordo com as intenções do promotor, as soluções do designer de interiores indicado pelo Cliente e as condicionantes do Projeto, ditadas pela legislação em vigor, pelos condicionalismos técnicos e pelos limites do custo da obra.\nIremos elaborar desenhos e elementos escritos que irão especificar todos os materiais e trabalhos necessários para a execução da obra. Está previsto que haja repetição das soluções, acabamentos e equipamentos a definir para as unidades de alojamento.\nA partir desses elementos é elaborado um Mapa de Quantidades e Medições, que lhe servirá de base para efetuar os pedidos de orçamento aos construtores, e uma Estimativa Orçamental, que irá usar como referência quando receber os orçamentos dos construtores. Faremos também a integração das soluções do designer de interiores indicado pelo Cliente no projeto de Arquitetura e a coordenação com os diferentes projetos de especialidades.", "key_activities_html": "<ul><li><p>Plantas gerais – escala 1:50;</p></li><li><p>Plantas de pavimentos e acabamentos – escala 1:50;</p></li><li><p>Plantas de tetos, indicando materiais e pontos de iluminação – escala 1:50;</p></li><li><p>Cortes e alçados – escala 1:50;</p></li><li><p>Detalhes de zonas específicas, tais como instalações sanitárias, kitchenettes e outras áreas conforme necessário – escala 1:20;</p></li><li><p>Mapas de vãos e de mobiliário fixo – escala apropriada;</p></li><li><p>Conjunto de detalhes construtivos – escala apropriada;</p></li><li><p>Coordenação com os projetos de especialidades.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nPlantas gerais – escala 1:50;\n\n\n\nPlantas de pavimentos e acabamentos – escala 1:50;\n\n\n\nPlantas de tetos, indicando materiais e pontos de iluminação – escala 1:50;\n\n\n\nCortes e alçados – escala 1:50;\n\n\n\nDetalhes de zonas específicas, tais como instalações sanitárias, kitchenettes e outras áreas conforme necessário – escala 1:20;\n\n\n\nMapas de vãos e de mobiliário fixo – escala apropriada;\n\n\n\nConjunto de detalhes construtivos – escala apropriada;\n\n\n\nCoordenação com os projetos de especialidades.\n\n", "stage_approval_html": "<p><strong>NOTA:</strong> É importante facultar-nos informação quanto aos limites do custo da obra, de forma a tomar decisões de acordo com as condicionantes.</p>", "stage_approval_text": "NOTA: É importante facultar-nos informação quanto aos limites do custo da obra, de forma a tomar decisões de acordo com as condicionantes."}}, {"id": "ac887a66-f0dc-4341-b206-e08d36d49c1e", "title": "Avença fase de obra", "sort_order": 170, "before": {"html": "<p></p>", "text": "", "client_info": "Calendário da obra e identificação do Empreiteiro Geral e da Fiscalização\nPedidos de esclarecimento e de aprovação de materiais submetidos pelo empreiteiro", "deliverables": "Participação em 2 reuniões de obra por mês.\nRespostas a pedidos de esclarecimento do empreiteiro.\nPareceres sobre desenhos de preparação de obra e pedidos de aprovação de materiais.\nDesenhos complementares, quando necessário.", "headingLevel": "h2", "objective_html": "<p>Na fase de construção, faremos o acompanhamento da obra através de reuniões com o Empreiteiro Geral, a Fiscalização e os restantes técnicos responsáveis pelos projetos de especialidades, tendo como objetivo garantir a correta interpretação do projeto de Arquitetura e o esclarecimento de eventuais dúvidas.</p>", "objective_text": "Na fase de construção, faremos o acompanhamento da obra através de reuniões com o Empreiteiro Geral, a Fiscalização e os restantes técnicos responsáveis pelos projetos de especialidades, tendo como objetivo garantir a correta interpretação do projeto de Arquitetura e o esclarecimento de eventuais dúvidas.", "client_info_visible": true, "key_activities_html": "<ul><li><p>Reuniões na obra com o Empreiteiro Geral, a Fiscalização e os projetistas das especialidades (2 por mês);</p></li><li><p>Resposta a dúvidas do Empreiteiro Geral através de outras reuniões, telefonemas e emails, para além das reuniões de obra;</p></li><li><p>Análise e parecer de desenhos de preparação de obra relativos à arquitetura;</p></li><li><p>Análise e parecer de pedidos de aprovação de materiais e equipamentos relativos à arquitetura – exclusivamente os que forem alternativas ao definido em projeto devido a eventuais incompatibilidades na obra;</p></li><li><p>Desenhos ou outros elementos adicionais que esclareçam dúvidas ou omissões do projeto de execução.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nReuniões na obra com o Empreiteiro Geral, a Fiscalização e os projetistas das especialidades (2 por mês);\n\n\n\nResposta a dúvidas do Empreiteiro Geral através de outras reuniões, telefonemas e emails, para além das reuniões de obra;\n\n\n\nAnálise e parecer de desenhos de preparação de obra relativos à arquitetura;\n\n\n\nAnálise e parecer de pedidos de aprovação de materiais e equipamentos relativos à arquitetura – exclusivamente os que forem alternativas ao definido em projeto devido a eventuais incompatibilidades na obra;\n\n\n\nDesenhos ou outros elementos adicionais que esclareçam dúvidas ou omissões do projeto de execução.\n\n", "stage_approval_html": "<p><strong>NOTA:</strong> A Assistência Técnica não constitui uma Fiscalização da Obra, nem a Gestão da Obra. Em caso de suspensão, interrupção ou cancelamento da obra, não serão cobrados os honorários relativos à Assistência Técnica à Obra.</p>", "stage_approval_text": "NOTA: A Assistência Técnica não constitui uma Fiscalização da Obra, nem a Gestão da Obra. Em caso de suspensão, interrupção ou cancelamento da obra, não serão cobrados os honorários relativos à Assistência Técnica à Obra."}, "after": {"html": "<p></p>", "text": "", "client_info": "Calendário da obra e identificação do Empreiteiro Geral e da Fiscalização\nPedidos de esclarecimento e de aprovação de materiais submetidos pelo empreiteiro", "deliverables": "Participação em 2 reuniões de obra por mês.\nRespostas a pedidos de esclarecimento do empreiteiro.\nPareceres sobre desenhos de preparação de obra e pedidos de aprovação de materiais.\nDesenhos complementares, quando necessário.", "headingLevel": "h2", "objective_html": "<p>Na fase de construção, faremos o acompanhamento da obra através de reuniões com o Empreiteiro Geral, a Fiscalização, o designer de interiores indicado pelo Cliente e os restantes técnicos responsáveis pelos projetos de especialidades, tendo como objetivo garantir a correta interpretação do projeto de Arquitetura e o esclarecimento de eventuais dúvidas.</p>", "objective_text": "Na fase de construção, faremos o acompanhamento da obra através de reuniões com o Empreiteiro Geral, a Fiscalização, o designer de interiores indicado pelo Cliente e os restantes técnicos responsáveis pelos projetos de especialidades, tendo como objetivo garantir a correta interpretação do projeto de Arquitetura e o esclarecimento de eventuais dúvidas.", "client_info_visible": true, "key_activities_html": "<ul><li><p>Reuniões na obra com o Empreiteiro Geral, a Fiscalização, o designer de interiores indicado pelo Cliente e os projetistas das especialidades (2 por mês);</p></li><li><p>Resposta a dúvidas do Empreiteiro Geral através de outras reuniões, telefonemas e emails, para além das reuniões de obra;</p></li><li><p>Análise e parecer de desenhos de preparação de obra relativos à arquitetura;</p></li><li><p>Análise e parecer de pedidos de aprovação de materiais e equipamentos relativos à arquitetura – exclusivamente os que forem alternativas ao definido em projeto devido a eventuais incompatibilidades na obra;</p></li><li><p>Desenhos ou outros elementos adicionais que esclareçam dúvidas ou omissões do projeto de execução.</p></li></ul><p></p>", "key_activities_text": "Reuniões na obra com o Empreiteiro Geral, a Fiscalização, o designer de interiores indicado pelo Cliente e os projetistas das especialidades (2 por mês);\nResposta a dúvidas do Empreiteiro Geral através de outras reuniões, telefonemas e emails, para além das reuniões de obra;\nAnálise e parecer de desenhos de preparação de obra relativos à arquitetura;\nAnálise e parecer de pedidos de aprovação de materiais e equipamentos relativos à arquitetura – exclusivamente os que forem alternativas ao definido em projeto devido a eventuais incompatibilidades na obra;\nDesenhos ou outros elementos adicionais que esclareçam dúvidas ou omissões do projeto de execução.", "stage_approval_html": "<p><strong>NOTA:</strong> A Assistência Técnica não constitui uma Fiscalização da Obra, nem a Gestão da Obra. Em caso de suspensão, interrupção ou cancelamento da obra, não serão cobrados os honorários relativos à Assistência Técnica à Obra.</p>", "stage_approval_text": "NOTA: A Assistência Técnica não constitui uma Fiscalização da Obra, nem a Gestão da Obra. Em caso de suspensão, interrupção ou cancelamento da obra, não serão cobrados os honorários relativos à Assistência Técnica à Obra."}}, {"id": "e957cde6-7d52-4542-9d71-1d3b90ffea87", "title": "Considerações Gerais", "sort_order": 270, "before": {"html": "<p>A presente proposta baseia-se nos parâmetros e no âmbito do projeto aqui descritos e na informação disponível à data da sua elaboração. Alterações relevantes ao programa, às áreas, ao âmbito do projeto, aos requisitos legais ou às instruções do cliente poderão implicar a revisão do âmbito dos serviços e dos respetivos honorários.</p><h3>Cessação do contrato</h3><p>O cliente poderá cessar o contrato em qualquer fase de projeto com a antecedência devida de 20 dias úteis, ficando responsável por pagar a totalidade da fase que estiver a decorrer.</p><h3>Suspensão do contrato</h3><p>Na eventualidade de ser necessário suspender o contrato por tempo indeterminado, por razões fora do controlo da equipa projetista, será cobrado um valor mensal de standby equivalente a 50% do valor das mensalidades do contrato.</p><p>As Medições e o Mapa de Quantidades do projeto de arquitetura, elaborados na fase de Projeto de Execução, estão incluídos nesta proposta. Este ponto prevalece sobre a exclusão de medições prevista no artigo 2.5 dos Termos Gerais.</p>", "text": "A presente proposta baseia-se nos parâmetros e no âmbito do projeto aqui descritos e na informação disponível à data da sua elaboração. Alterações relevantes ao programa, às áreas, ao âmbito do projeto, aos requisitos legais ou às instruções do cliente poderão implicar a revisão do âmbito dos serviços e dos respetivos honorários.\n\nCessação do contrato\n\nO cliente poderá cessar o contrato em qualquer fase de projeto com a antecedência devida de 20 dias úteis, ficando responsável por pagar a totalidade da fase que estiver a decorrer.\n\nSuspensão do contrato\n\nNa eventualidade de ser necessário suspender o contrato por tempo indeterminado, por razões fora do controlo da equipa projetista, será cobrado um valor mensal de standby equivalente a 50% do valor das mensalidades do contrato.\n\nAs Medições e o Mapa de Quantidades do projeto de arquitetura, elaborados na fase de Projeto de Execução, estão incluídos nesta proposta. Este ponto prevalece sobre a exclusão de medições prevista no artigo 2.5 dos Termos Gerais.", "headingLevel": "h1"}, "after": {"html": "<p>A presente proposta baseia-se nos parâmetros e no âmbito do projeto aqui descritos e na informação disponível à data da sua elaboração. Alterações relevantes ao programa, às áreas, ao âmbito do projeto, aos requisitos legais ou às instruções do cliente poderão implicar a revisão do âmbito dos serviços e dos respetivos honorários.</p><h3>Cessação do contrato</h3><p>O cliente poderá cessar o contrato em qualquer fase de projeto com a antecedência devida de 20 dias úteis, ficando responsável por pagar a totalidade da fase que estiver a decorrer.</p><h3>Suspensão do contrato</h3><p>Na eventualidade de ser necessário suspender o contrato por tempo indeterminado, por razões fora do controlo da equipa projetista, será cobrado um valor mensal de standby equivalente a 50% do valor das mensalidades do contrato.</p><p>As Medições e o Mapa de Quantidades do projeto de arquitetura, elaborados na fase de Projeto de Execução, estão incluídos nesta proposta. Este ponto prevalece sobre a exclusão de medições prevista no artigo 2.5 dos Termos Gerais.</p><p>A PSA é a autora e coordenadora do projeto de arquitetura, em parceria com o designer de interiores indicado pelo Cliente. O cumprimento dos prazos de cada fase depende da receção atempada dos elementos a fornecer pelo Cliente e pelo designer de interiores.</p>", "text": "A presente proposta baseia-se nos parâmetros e no âmbito do projeto aqui descritos e na informação disponível à data da sua elaboração. Alterações relevantes ao programa, às áreas, ao âmbito do projeto, aos requisitos legais ou às instruções do cliente poderão implicar a revisão do âmbito dos serviços e dos respetivos honorários.\nCessação do contrato\nO cliente poderá cessar o contrato em qualquer fase de projeto com a antecedência devida de 20 dias úteis, ficando responsável por pagar a totalidade da fase que estiver a decorrer.\nSuspensão do contrato\nNa eventualidade de ser necessário suspender o contrato por tempo indeterminado, por razões fora do controlo da equipa projetista, será cobrado um valor mensal de standby equivalente a 50% do valor das mensalidades do contrato.\nAs Medições e o Mapa de Quantidades do projeto de arquitetura, elaborados na fase de Projeto de Execução, estão incluídos nesta proposta. Este ponto prevalece sobre a exclusão de medições prevista no artigo 2.5 dos Termos Gerais.\nA PSA é a autora e coordenadora do projeto de arquitetura, em parceria com o designer de interiores indicado pelo Cliente. O cumprimento dos prazos de cada fase depende da receção atempada dos elementos a fornecer pelo Cliente e pelo designer de interiores.", "headingLevel": "h1"}}, {"id": "c86dcb13-3ba9-414b-9eac-359b0a165f6a", "title": "Exclusões", "sort_order": 280, "before": {"html": "<p>Estão excluídos da proposta:</p><ul><li><p>IVA à taxa legal em vigor;</p></li><li><p>Despesas de deslocação, como viagens, alojamento, refeições e despesas diversas associadas, fora do concelho de Lisboa, que não estejam contempladas no capítulo da Assistência Técnica;</p></li><li><p>Todos os serviços especializados necessários ao desenvolvimento do projeto, como levantamentos topográficos e arquitetónicos, estudos geotécnicos e geológicos, etc.;</p></li><li><p>Taxas camarárias e taxas de outras entidades;</p></li><li><p>Projetos de especialidades e de paisagismo;</p></li><li><p>Preparação e lançamento de concurso de empreitadas;</p></li><li><p>Direção técnica da obra, administração da obra, coordenação e fiscalização da obra;</p></li><li><p>Elaboração de desenhos de preparação de obra;</p></li><li><p>Maquetes profissionais;</p></li><li><p>Imagens 3D para além das 6 incluídas no Estudo prévio;</p></li><li><p>Projeto de decoração de interiores e de mobiliário, equipamento e decoração (FF&amp;E), salvo se contratado como serviço opcional;</p></li><li><p>Projetos especiais (cozinhas técnicas, piscinas e spa);</p></li><li><p>Pedidos ou negociações para a obtenção de financiamentos (privados ou corporate);</p></li><li><p>Processo de classificação do empreendimento turístico junto do Turismo de Portugal após a conclusão da obra, e registo ou autorização de exploração;</p></li><li><p>Certificação energética e acústica.</p></li></ul><p></p>", "text": "Estão excluídos da proposta:\n\n\n\n\n\nIVA à taxa legal em vigor;\n\n\n\nDespesas de deslocação, como viagens, alojamento, refeições e despesas diversas associadas, fora do concelho de Lisboa, que não estejam contempladas no capítulo da Assistência Técnica;\n\n\n\nTodos os serviços especializados necessários ao desenvolvimento do projeto, como levantamentos topográficos e arquitetónicos, estudos geotécnicos e geológicos, etc.;\n\n\n\nTaxas camarárias e taxas de outras entidades;\n\n\n\nProjetos de especialidades e de paisagismo;\n\n\n\nPreparação e lançamento de concurso de empreitadas;\n\n\n\nDireção técnica da obra, administração da obra, coordenação e fiscalização da obra;\n\n\n\nElaboração de desenhos de preparação de obra;\n\n\n\nMaquetes profissionais;\n\n\n\nImagens 3D para além das 6 incluídas no Estudo prévio;\n\n\n\nProjeto de decoração de interiores e de mobiliário, equipamento e decoração (FF&E), salvo se contratado como serviço opcional;\n\n\n\nProjetos especiais (cozinhas técnicas, piscinas e spa);\n\n\n\nPedidos ou negociações para a obtenção de financiamentos (privados ou corporate);\n\n\n\nProcesso de classificação do empreendimento turístico junto do Turismo de Portugal após a conclusão da obra, e registo ou autorização de exploração;\n\n\n\nCertificação energética e acústica.\n\n", "headingLevel": "h1"}, "after": {"html": "<p>Estão excluídos da proposta:</p><ul><li><p>IVA à taxa legal em vigor;</p></li><li><p>Despesas de deslocação, como viagens, alojamento, refeições e despesas diversas associadas, fora do concelho de Lisboa, que não estejam contempladas no capítulo da Assistência Técnica;</p></li><li><p>Todos os serviços especializados necessários ao desenvolvimento do projeto, como levantamentos topográficos e arquitetónicos, estudos geotécnicos e geológicos, etc.;</p></li><li><p>Taxas camarárias e taxas de outras entidades;</p></li><li><p>Projetos de especialidades e de paisagismo;</p></li><li><p>Preparação e lançamento de concurso de empreitadas;</p></li><li><p>Direção técnica da obra, administração da obra, coordenação e fiscalização da obra;</p></li><li><p>Elaboração de desenhos de preparação de obra;</p></li><li><p>Maquetes profissionais;</p></li><li><p>Imagens 3D para além das 6 incluídas no Estudo prévio;</p></li><li><p>Projeto de design de interiores, incluindo mobiliário, equipamento e decoração (FF&amp;E), a cargo do designer de interiores indicado pelo Cliente;</p></li><li><p>Projetos especiais (cozinhas técnicas, piscinas e spa);</p></li><li><p>Pedidos ou negociações para a obtenção de financiamentos (privados ou corporate);</p></li><li><p>Processo de classificação do empreendimento turístico junto do Turismo de Portugal após a conclusão da obra, e registo ou autorização de exploração;</p></li><li><p>Certificação energética e acústica.</p></li></ul><p></p>", "text": "Estão excluídos da proposta:\nIVA à taxa legal em vigor;\nDespesas de deslocação, como viagens, alojamento, refeições e despesas diversas associadas, fora do concelho de Lisboa, que não estejam contempladas no capítulo da Assistência Técnica;\nTodos os serviços especializados necessários ao desenvolvimento do projeto, como levantamentos topográficos e arquitetónicos, estudos geotécnicos e geológicos, etc.;\nTaxas camarárias e taxas de outras entidades;\nProjetos de especialidades e de paisagismo;\nPreparação e lançamento de concurso de empreitadas;\nDireção técnica da obra, administração da obra, coordenação e fiscalização da obra;\nElaboração de desenhos de preparação de obra;\nMaquetes profissionais;\nImagens 3D para além das 6 incluídas no Estudo prévio;\nProjeto de design de interiores, incluindo mobiliário, equipamento e decoração (FF&E), a cargo do designer de interiores indicado pelo Cliente;\nProjetos especiais (cozinhas técnicas, piscinas e spa);\nPedidos ou negociações para a obtenção de financiamentos (privados ou corporate);\nProcesso de classificação do empreendimento turístico junto do Turismo de Portugal após a conclusão da obra, e registo ou autorização de exploração;\nCertificação energética e acústica.", "headingLevel": "h1"}}, {"id": "9569d0f6-2311-45bf-9656-86fd64ab7d2e", "title": "Serviço opcional – Design de Interiores", "sort_order": 260, "before": {"scope_html": "<ul><li><p>Conceito de design de interiores;</p></li><li><p>Seleção de materiais e acabamentos;</p></li><li><p>Desenhos gerais de interiores;</p></li><li><p>Projeto de mobiliário fixo e carpintarias;</p></li><li><p>Projeto das instalações sanitárias;</p></li><li><p>Coordenação de mobiliário, equipamento e decoração (FF&amp;E);</p></li><li><p>Coordenação da iluminação;</p></li><li><p>Especificações de interiores;</p></li><li><p>Documentação para concurso;</p></li><li><p>Assistência técnica à obra.</p></li></ul><p></p>", "scope_text": "\n\n\n\nConceito de design de interiores;\n\n\n\nSeleção de materiais e acabamentos;\n\n\n\nDesenhos gerais de interiores;\n\n\n\nProjeto de mobiliário fixo e carpintarias;\n\n\n\nProjeto das instalações sanitárias;\n\n\n\nCoordenação de mobiliário, equipamento e decoração (FF&E);\n\n\n\nCoordenação da iluminação;\n\n\n\nEspecificações de interiores;\n\n\n\nDocumentação para concurso;\n\n\n\nAssistência técnica à obra.\n\n", "headingLevel": "h1", "objective_html": "<p>A Pedra Silva Arquitectos disponibiliza um serviço integrado de Design de Interiores, que desenvolve a experiência do hóspede nas unidades de alojamento e nas áreas comuns, para além do projeto de arquitetura.</p><p>O trabalho desenvolvido pela mesma equipa multidisciplinar assegura a continuidade entre o conceito arquitetónico e o ambiente interior, permitindo coordenar as decisões de design desde as primeiras fases do projeto. Os honorários deste serviço serão apresentados mediante pedido do cliente.</p>", "objective_text": "A Pedra Silva Arquitectos disponibiliza um serviço integrado de Design de Interiores, que desenvolve a experiência do hóspede nas unidades de alojamento e nas áreas comuns, para além do projeto de arquitetura.\n\nO trabalho desenvolvido pela mesma equipa multidisciplinar assegura a continuidade entre o conceito arquitetónico e o ambiente interior, permitindo coordenar as decisões de design desde as primeiras fases do projeto. Os honorários deste serviço serão apresentados mediante pedido do cliente."}, "after": {"scope_html": "<ul><li><p>Conceito de design de interiores;</p></li><li><p>Seleção de materiais e acabamentos;</p></li><li><p>Desenhos gerais de interiores;</p></li><li><p>Projeto de mobiliário fixo e carpintarias;</p></li><li><p>Projeto das instalações sanitárias;</p></li><li><p>Coordenação de mobiliário, equipamento e decoração (FF&amp;E);</p></li><li><p>Coordenação da iluminação;</p></li><li><p>Especificações de interiores;</p></li><li><p>Documentação para concurso;</p></li><li><p>Assistência técnica à obra.</p></li></ul><p></p>", "scope_text": "\n\n\n\nConceito de design de interiores;\n\n\n\nSeleção de materiais e acabamentos;\n\n\n\nDesenhos gerais de interiores;\n\n\n\nProjeto de mobiliário fixo e carpintarias;\n\n\n\nProjeto das instalações sanitárias;\n\n\n\nCoordenação de mobiliário, equipamento e decoração (FF&E);\n\n\n\nCoordenação da iluminação;\n\n\n\nEspecificações de interiores;\n\n\n\nDocumentação para concurso;\n\n\n\nAssistência técnica à obra.\n\n", "headingLevel": "h1", "objective_html": "<p>A Pedra Silva Arquitectos disponibiliza um serviço integrado de Design de Interiores, que desenvolve a experiência do hóspede nas unidades de alojamento e nas áreas comuns, para além do projeto de arquitetura.</p><p>O trabalho desenvolvido pela mesma equipa multidisciplinar assegura a continuidade entre o conceito arquitetónico e o ambiente interior, permitindo coordenar as decisões de design desde as primeiras fases do projeto. Os honorários deste serviço serão apresentados mediante pedido do cliente.</p>", "objective_text": "A Pedra Silva Arquitectos disponibiliza um serviço integrado de Design de Interiores, que desenvolve a experiência do hóspede nas unidades de alojamento e nas áreas comuns, para além do projeto de arquitetura.\n\nO trabalho desenvolvido pela mesma equipa multidisciplinar assegura a continuidade entre o conceito arquitetónico e o ambiente interior, permitindo coordenar as decisões de design desde as primeiras fases do projeto. Os honorários deste serviço serão apresentados mediante pedido do cliente.", "html": "<p>Nesta proposta, o conceito e o projeto de design de interiores são da responsabilidade do designer de interiores indicado pelo Cliente. A PSA integra as suas soluções no projeto de arquitetura e assegura a articulação com as especialidades; esta integração está incluída no âmbito de arquitetura e não corresponde à prestação do serviço opcional de design de interiores. Qualquer contratação adicional de design de interiores à PSA dependerá de acordo separado e não substitui o âmbito do designer indicado pelo Cliente.</p>"}}]$changes$::jsonb) LOOP
UPDATE public.psa_proposal_blocks SET content_rich=c->'after' WHERE proposal_id=np AND sort_order=(c->>'sort_order')::int AND title=c->>'title';
IF NOT FOUND THEN RAISE EXCEPTION 'Missing new revision block: %',c->>'title'; END IF;
count_changed:=count_changed+1;
END LOOP;
INSERT INTO public.quote_billable_hourly_rates(quote_id,role_name,sale_rate,default_inherited) SELECT n,role_name,sale_rate,false FROM public.quote_billable_hourly_rates WHERE quote_id=chi AND role_name IN('partner','director','senior_architect','architect','lead_designer','junior_architect') ON CONFLICT(quote_id,role_name) DO UPDATE SET sale_rate=excluded.sale_rate,default_inherited=false;
total_after:=public.fee_proposal_resolved_value(n);
IF total_before IS DISTINCT FROM total_after THEN RAISE EXCEPTION 'Fee changed: % -> %',total_before,total_after; END IF;
IF before_blocks IS DISTINCT FROM (SELECT jsonb_agg(to_jsonb(b) ORDER BY id) FROM public.psa_proposal_blocks b WHERE proposal_id=(SELECT main_proposal_id FROM public.fee_proposals WHERE id=src)) THEN RAISE EXCEPTION 'Source blocks changed'; END IF;
IF chi_before IS DISTINCT FROM (SELECT jsonb_build_object('quote',to_jsonb(q),'blocks',(SELECT jsonb_agg(to_jsonb(b) ORDER BY id) FROM public.psa_proposal_blocks b WHERE proposal_id=q.main_proposal_id)) FROM public.fee_proposals q WHERE id=chi) THEN RAISE EXCEPTION 'Chiado changed'; END IF;
IF (SELECT count(*) FROM public.quote_payment_schedule_items WHERE quote_id=src)<>(SELECT count(*) FROM public.quote_payment_schedule_items WHERE quote_id=n) OR (SELECT sum(amount_value) FROM public.quote_payment_schedule_items WHERE quote_id=src) IS DISTINCT FROM (SELECT sum(amount_value) FROM public.quote_payment_schedule_items WHERE quote_id=n) THEN RAISE EXCEPTION 'Payment schedule changed'; END IF;
RAISE NOTICE 'New quote %, document %, changed blocks %, fee before/after %',n,np,count_changed,total_after;
END $op$;
